entry.content:
最近开发中，关于for循环踩了一点坑，在此记录一下。分享一下关于for循环对数组的遍历

1.从小到大依次输出
static void Main(string[] args)&#123;    /*需要遍历的数组*/    int[] i = &#123;1,2,3,4,5&#125;;    /*for循环对数组的值从小到大输出*/    for (int j = 0; j &lt; i.Length; j ++)    &#123;        Console.WriteLine(i[j]);    &#125;&#125;
依次输出：123452.从大到小依次输出
static void Main(string[] args)&#123;    /*需要遍历的数组*/    int[] i = &#123;1,2,3,4,5&#125;;    /*for循环对数组的值从大到小输出*/    for (int j = i.Length - 1; j &gt; -1; j --)    &#123;        Console.WriteLine(i[j]);    &#125;&#125;
依次输出：54321

开发中可能会有按照字节数截取字符串的需求。当字符串超过指定字节，保留指定字节数长度的字符串，超过部分舍掉。C#中的GetString(Byte[], Int32, Int32)方法是可以直接截取指定字节，将字节转为字符串，但是此方法会有一个问题：

如果一个全角字符占据两个字节，被裁剪字符串时，下剪的位置恰好将一个全角字符减成两半，那显示出来的字符串的最后面会出现一个问号（？）。这里提供一个解决方案，仅供参考（以UTF8编码为例）
/*需要截取的字符串*/string test = &quot;需要截取的字符串&quot;; //UTF8编码，一个汉字三个字节/*需要截取的字节长度*/int spitLength = 20;/*截取后的字符串*/string testResult = string.Empty;/*截取的字符串字节长度大于需要截取的字节长度*/if (Encoding.UTF8.GetBytes(test).Length &gt; spitLength)&#123;    /*字符串字节长度初期化（0）*/    int len = 0;    /*字符串StringBuilder*/    StringBuilder strTmp= new StringBuilder();    /*对要截取的字符串遍历，累加每个字符的字节长度*/    foreach (char item in test)    &#123;        /*累加每个字符的字节长度*/        len = len + Encoding.UTF8.GetBytes(item.ToString()).Length;        /*累加的长度大于截取的长度时，跳出循环*/        if (len &gt; spitLength)        &#123;            break;        &#125;        else        &#123;            /*将当前的字符追加到字符串StringBuilder*/            strTmp.Append(item);        &#125;    &#125;    /*将字符串StringBuilder赋值给截取后的字符串*/    testResult = strTmp.ToString();&#125;Console.WriteLine(testResult);/*输出：需要截取的字*/
原理就是反向将要截取的字符串逐个字符累加，算字节数，与要截取的字节数比较，如果累加完当前字符的字节数大于要截取的字节数时，舍弃当前字符，跳出累加，将累加的字符赋值给要截取的字符。
想着另起一篇文章，但是想想，还是写在一起吧，以下内容与标题无关。C#中StreamReader.ReadLine中的ReadLine如何初期化？StreamReader.ReadLine 方法：从当前流中读取一行字符并将数据作为字符串返回我打开了一个文件流，但是我想对这个文件用ReadLine连续读取两遍，第一遍判断文件是否满足所要求的行数，第二遍则对每行数据进行处理。
/*读取的文件路径*/string path = @&quot;c:\temp\MyTest.txt&quot;;/*读取文件*/StreamReader sr = new StreamReader(path);/*行数初期化*/int rowCounts = 0;/*最大行数*/int maxCounts = 2;/*遍历文件行数*/while (sr.ReadLine() != null)&#123;    /*行数加算*/    rowCounts ++;    if (rowCounts &gt; maxCounts)    &#123;        /*行数大于最大行数时结束循环*/        break;    &#125;&#125;/*第二次读取文件*//*清除内部缓冲区*/sr.DiscardBufferedData(); //初期化ReadLine/*文件重新读取*/sr.BaseStream.Position = 0; //初期化ReadLinestring line = string.Empty;while ((line = sr.ReadLine()) != null)&#123;    /*从第一行开始按行处理文件*/&#125;/*文件读取完成后请关闭StreamReader*/sr.Close();
如果不加上中间的两步初期化ReadLine，在下一次循环时，则按照第一次循环结束的位置继续读取，导致第二次循环时缺少了第一次循环所用到的数据。微软文档说清除内部缓冲区会影响性能，不到万不得已时不建议使用，所以还有一种方法：第一次循环完成后，关闭StreamReader，第二次循环开始前，重新打开StreamReader，貌似有点费劲，看自己的需求吧。如果不使用清除内部缓冲区，直接使用Position = 0则会造成数据重读，即在第一次读完的基础上继续读取，读取完成后，再次从第一行开始读取，读至最后。

在这里记录一下自己用原生js实现jquery的部分方法，算是jquery转js吧持续更新


$(&quot;.code&quot;).on(&quot;click&quot;,&quot;#js-btn-copy&quot;,function(){})标题实现对class的子元素绑定click事件，原生js实现

var copyButton=document.querySelectorAll(&quot;.code #js-btn-copy&quot;);for(var i in copyButton)&#123;    copyButton[i].onclick=function(button)&#123;&#125;&#125;
如果想把onclick绑定的函数单独定义一个方法为button()，则
function button()&#123;&#125;;var copyButton=document.querySelectorAll(&quot;.code #js-btn-copy&quot;);for(var i in copyButton)&#123;    copyButton[i].onclick=button;&#125;
copyButton[i].onclick=button;这里等于的是button而不是button()，如果直接在html标签里面添加onclick事件，是onclick=&quot;button()&quot;。2. $(ele).html(value)js实现：ele.innerHTML=value3. $(ele).mouseout(function(){})js：ele.onmouseout=function(){}对应的，jq的$(ele).mouseover(function(){})也是这样实现4. $(&#39;.toc-child&#39;).hide();这个可以用js封装函数实现
function tocChild(key,value)&#123;    var $toc_child=document.getElementsByClassName(&quot;toc-child&quot;);    for(var i=0;i&lt;$toc_child.length;i++)&#123;      $toc_child[i].style.cssText=key+&quot;:&quot;+value;    &#125;&#125;tocChild(&quot;display&quot;,&quot;none&quot;)

$(name).offset()获取offset，js有name.offsetTop和name.offsetLeft方法分享一个获取元素绝对位置的方法

function getElementTop(element)&#123;    var actualTop=element.offsetTop;    var current=element.offsetParent;    while(current!==null)&#123;      actualTop+=current.offsetTop;      current=current.offsetParent;    &#125;    return actualTop;&#125;
jquery中有一个position()方法，这个还没有整清楚如何实现，所以主题中目录优化部分还是没有去除jquery6. $(&#39;body,html&#39;).animate({scrollTop: scrollOffset.top-50},1000);题目是jq封装的一个锚点跳转方法，也就是页面平滑滚动，这里分享一个js封装的方法，功能大致相同
// 页面平滑滚动var timer=null;function slideTo(targetPageY,element)&#123;    if(timer)&#123;      clearInterval(timer);    &#125;    timer=setInterval(function()&#123;        //当前高度        var scrollY=element.scrollTop;        //剩余距离        var distance=targetPageY&gt;scrollY?targetPageY-scrollY:scrollY-targetPageY;        //每时每刻速度        var speed=Math.ceil(distance/10);        if(parseInt(targetPageY)==parseInt(scrollY))&#123;        clearInterval(timer);        &#125;else&#123;        element.scrollTop=targetPageY&gt;scrollY?scrollY+speed:scrollY-speed;        &#125;    &#125;,10)&#125;
传入两个参数targetPageY,element，其中：targetPageY：滚动位置element：滚动条所在容器支持向上向下滚动，速度调节speed7. $(ele).scrollTop();js：var eleTop =ele.scrollTop;8. $(window).scroll(function() {})题目是滚动监听，js实现：window.addEventListener(&#39;scroll&#39;, (e) =&gt; {})jq很多监听之类的函数，都可以通过js的addEventListener实现9. $(window).load(function() {});同上，添加addEventListener，即：window.addEventListener(&quot;load&quot;,function(){})window.addEventListener(&quot;load&quot;,function(){})不同于window.onload=function(){}window.onload=function(){}只能执行一次，通常不建议使用。10. jquery中ready方法js的addEventListener中有一个DOMContentLoaded，实现ready方法，用法同上window.addEventListener(&quot;DOMContentLoaded&quot;,function(){})11. jquery中ajax方法
$.ajax(&#123;  url: path,  dataType: &quot;xml&quot;,  success: function (xmlResponse) &#123;      // get the contents from search data      var datas = $(&quot;entry&quot;, xmlResponse).map(function () &#123;          return &#123;              title: $(&quot;title&quot;, this).text(),              content: $(&quot;content&quot;, this).text(),              url: $(&quot;url&quot;, this).text()          &#125;;      &#125;).get();  &#125;&#125;)
原生js中提供了fetch方法
fetch(path).then(response =&gt; response.text()).then(str =&gt; new window.DOMParser().parseFromString(str, &#x27;text/xml&#x27;)).then(data =&gt; &#123;    const datas = [...data.querySelectorAll(&#x27;entry&#x27;)].map(function (item) &#123;        return &#123;            title: item.querySelector(&#x27;title&#x27;).textContent,            content: item.querySelector(&#x27;content&#x27;).textContent,            url: item.querySelector(&#x27;url&#x27;).textContent        &#125;    &#125;);&#125;)

js中querySelector()与querySelectorAll()方法
querySelector() 方法返回文档中匹配指定 CSS 选择器的一个元素。用法与$()获取元素相同，但是只返回一个元素。实例

//获取文档中 id=&quot;demo&quot; 的元素：document.querySelector(&quot;#demo&quot;);
document可以更换为已经获取的元素实例
//获取文档中 id=&#x27;header&#x27;的元素var $header=document.getElementById(&#x27;header&#x27;);//在获取的id=&#x27;header&#x27;元素中获取class=&quot;example&quot; 的第一个元素:var $example=$header.querySelector(&quot;.example&quot;);
确保$header已经获取到元素，否则控制台报错：Cannot read property &#39;querySelector&#39; of undefined如果不确定$header是否获取到元素，防止控制台报错，建议直接使用document.querySelector(&quot;#header .example&quot;)

querySelectorAll() 方法返回文档中匹配指定 CSS 选择器的所有元素，返回 NodeList 对象。简言之，querySelectorAll() 方法返回的是一个数组，使用时需要对其遍历，遍历方法参考1。querySelectorAll() 方法与getElementsByClassName() 方法返回的数据均为数组，不同在于querySelectorAll()支持jquery选择器，与querySelector()使用方法相同实例

//获取文档中 id=&quot;demo&quot; 的元素：document.querySelectorAll(&quot;#demo&quot;)[0];
document可以更换为已经获取的元素，需要注意的点与querySelector() 方法相同。


最后，截至目前，本主题只剩1个功能还需要jquery，这个有点难度。13. $(name).position().top
function getPositionTop(element)&#123;    // 相对于窗口的位置    const activeTop = element.getBoundingClientRect().top;    // 最近祖先元素相对于窗口的位置    const activeParentTop = element.offsetParent.getBoundingClientRect().top;    return activeTop-activeParentTop;&#125;
貌似可以使用offsetTop来替换getBoundingClientRect().top，可以自行尝试是否满足自己的需求

最近浏览原神米游社，发现页面重新进入后页面浏览位置没有改变，上网查询了一些资料，在自己博客主题上实现了这个功能，在此分享一下

在网上查询的资料中得知，此功能可以通过js实现，在页面关闭或刷新时，调用window.onbeforeunload函数将当前页面滚动条的滚动高度存储在当前页面的cookie中，页面载入时，读取当前页面cookie中存储的滚动条高度，跳转到对应的位置，以下是源码20220528更新：添加判断记录位置是否为0
window.onbeforeunload = function()&#123;    var scrollPos;        if (typeof window.pageYOffset != &#x27;undefined&#x27;) &#123;        scrollPos = window.pageYOffset;    &#125;    else if (typeof document.compatMode != &#x27;undefined&#x27; &amp;&amp;        document.compatMode != &#x27;BackCompat&#x27;) &#123;        scrollPos = document.documentElement.scrollTop;    &#125;    else if (typeof document.body != &#x27;undefined&#x27;) &#123;        scrollPos = document.body.scrollTop;    &#125;    document.cookie=&quot;scrollTop=&quot;+scrollPos; //存储滚动条位置到cookies中&#125;window.onload = function()&#123;     if(document.cookie.match(/scrollTop=([^;]+)(;|$)/)!=null)&#123;        var arr=document.cookie.match(/scrollTop=([^;]+)(;|$)/); //cookies中不为空，则读取滚动条位置        // 大于0时跳转至上次记录位置        if(parseInt(arr[1]) &gt; 0)&#123;          document.documentElement.scrollTop=parseInt(arr[1]);          document.body.scrollTop=parseInt(arr[1]);        &#125;    &#125;&#125;
由于yilia主题的特殊性（pc页面滚动时window.pageYOffset，document.documentElement.scrollTop，document.body.scrollTop均为0），在这里附上自己适配yilia主题的代码。
/*记录文章页面当前位置*/if(yiliaConfig.isPost&amp;&amp;yiliaConfig.scrollPos)&#123;  //在即将离开当前页面（刷新或关闭）时触发  window.onbeforeunload = function()&#123;    var scrollPos=$(&#x27;#container&#x27;).scrollTop() || document.documentElement.scrollTop || document.body.scrollTop;    document.cookie=&quot;scrollTop=&quot;+scrollPos; //存储滚动条位置到cookies中  &#125;  //在离在开网页时（点击链接，刷新页面，关闭浏览器等）触发  window.onpagehide = function()&#123;    var scrollPos=$(&#x27;#container&#x27;).scrollTop() || document.documentElement.scrollTop || document.body.scrollTop;    document.cookie=&quot;scrollTop=&quot;+scrollPos; //存储滚动条位置到cookies中  &#125;  $(document).ready(function()&#123;//建议使用：$(window).on(&#x27;load&#x27;,function()&#123;...&#125;)    if(document.cookie.match(/scrollTop=([^;]+)(;|$)/)!=null)&#123;      var arr=document.cookie.match(/scrollTop=([^;]+)(;|$)/); //cookies中不为空，则读取滚动条位置      // 大于0时跳转至上次记录位置      if(parseInt(arr[1]) &gt; 0)&#123;        $(&#x27;#container&#x27;).scrollTop(parseInt(arr[1]));        document.documentElement.scrollTop=parseInt(arr[1]);        document.body.scrollTop=parseInt(arr[1]);      &#125;    &#125;  &#125;)&#125;
其中，yiliaConfig.isPost判断当前页面是否为文章页，yiliaConfig.scrollPos为自添加属性，判断是否开启此功能。因为window.onpagehide在mobile端浏览器存在不被触发的情况，所以添加window.onpagehide事件，解决大部分情况，事件区别可自行到相关网站查询。
补充：$(document).ready(function(){…})函数可以简写为$(function{…})，此方法在dom结构加载完毕后执行，如果页面中有一些加载较慢的资源（如图片），不建议使用此方法，会使页面在还没有显示完整时跳转，导致出现问题。这里说一个js原生方法：window.onload，此方法是在页面全部加载完毕后执行，但是只能执行一次，如果多次使用，后面会覆盖前面，不推荐使用。既然不推荐使用，就换一个方法，用jq实现window.onload方法：$(window).on(‘load’,function(){…})，此方法与window.onload方法功能一致，但是没有只能实现一次的限制，可多次使用，不会覆盖。网站上查询的资料里此方法多半写成：$(window).load(function(){…})，这仿佛是jq较早版本支持的方法，新版本已不能使用。

本篇文章对springMVC进行简单介绍

spring介绍spring是一个开源的控制反转(Inversion of Control ,IoC)和面向切面(AOP)的容器框架.它的主要目的是简化企业开发.
所谓控制反转就是应用本身不负责依赖对象的创建及维护，依赖对象的创建及维护是由外部容器负责的。这样控制权就由应用转移到了外部容器，控制权的转移就是所谓反转。
面向切面，通过预编译方式和运行期动态代理实现程序功能的统一维护的一种技术.利用AOP可以对业务逻辑的各个部分进行隔离，从而使得业务逻辑各部分之间的耦合度降低，提高程序的可重用性，同时提高了开发的效率。
创建工程创建工程，引入jar包创建各目录，并创建配置文件SqlConfigMap.xmlapplicationContext.xml在applicationContext.xml中配置数据源在applicationContext.xml中配置sqlSessionFactory
SqlConfigMap.xml配置typeAliases为别名配置，可省略domain的包名&lt;!--别名配置  --&gt; 	&lt;typeAliases&gt; 		&lt;package name=&quot;com.aly.domain&quot;/&gt; 	&lt;/typeAliases&gt;mappers中package为扫描配置&lt;!-- 加载映射文件 --&gt;  	&lt;mappers&gt;  		&lt;package name=”com.aly.mapper”/&gt;  	&lt;/mappers&gt;&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;!DOCTYPE configuration PUBLIC &quot;-//mybatis.org//DTD Config 3.0//EN&quot; &quot;http://mybatis.org/dtd/mybatis-3-config.dtd&quot;&gt; &lt;configuration&gt; 	&lt;settings&gt;   		&lt;setting name=&quot;lazyLoadingEnabled&quot; value=&quot;true&quot;/&gt;   		&lt;setting name=&quot;aggressiveLazyLoading&quot; value=&quot;false&quot;/&gt;   &lt;/settings&gt;     	&lt;!-- 加载映射文件 --&gt;  	&lt;mappers&gt;  		&lt;mapper resource=&quot;com/aly/mapper/UserMapper.xml&quot;/&gt;  		&lt;mapper resource=&quot;com/aly/mapper/OrdersMapper.xml&quot;/&gt;  		&lt;mapper resource=&quot;com/aly/mapper/OrderdetailMapper.xml&quot;/&gt;  	&lt;/mappers&gt;&lt;/configuration&gt;

applicationContext.xml配置&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;	xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot; xmlns:mvc=&quot;http://www.springframework.org/schema/mvc&quot;	xmlns:context=&quot;http://www.springframework.org/schema/context&quot;	xmlns:aop=&quot;http://www.springframework.org/schema/aop&quot; xmlns:tx=&quot;http://www.springframework.org/schema/tx&quot;	xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans 		http://www.springframework.org/schema/beans/spring-beans-3.2.xsd 		http://www.springframework.org/schema/mvc 		http://www.springframework.org/schema/mvc/spring-mvc-3.2.xsd 		http://www.springframework.org/schema/context 		http://www.springframework.org/schema/context/spring-context-3.2.xsd 		http://www.springframework.org/schema/aop 		http://www.springframework.org/schema/aop/spring-aop-3.2.xsd 		http://www.springframework.org/schema/tx 		http://www.springframework.org/schema/tx/spring-tx-3.2.xsd &quot;&gt;&lt;/beans&gt;数据源的配置，需要放在beans里面destroy-method为是否自动销毁连接maxActive为最大活跃连接数maxIdle最大空闲连接数&lt;bean id=&quot;dataSource&quot; class=&quot;org.apache.commons.dbcp.BasicDataSource&quot;		destroy-method=&quot;close&quot;&gt;			&lt;property name=&quot;driverClassName&quot; value=&quot;com.mysql.jdbc.Driver&quot;/&gt;			&lt;property name=&quot;url&quot; value=&quot;jdbc:mysql://localhost:3306/ssm&quot;/&gt;			&lt;property name=&quot;username&quot; value=&quot;root&quot;/&gt;			&lt;property name=&quot;password&quot; value=&quot;&quot;/&gt;			&lt;!-- 连接活跃最大值（最大连接数） --&gt;			&lt;property name=&quot;maxActive&quot; value=&quot;10&quot;/&gt;			&lt;!-- 最大空闲连接数 --&gt;			&lt;property name=&quot;maxIdle&quot; value=&quot;5&quot;/&gt;		&lt;/bean&gt;配置sqlSessionFactory交给spring管理的过程为控制反转配置文件中直接传入参数为依赖注入（控制反转的一种方式）两个必要参数mybatis核心配置文件和数据源&lt;bean id=&quot;sqlSessionFactory&quot; class=&quot;org.mybatis.spring.SqlSessionFactoryBean&quot;&gt;			&lt;property name=&quot;configLocation&quot; value=&quot;SqlMapConfig.xml&quot;/&gt;			&lt;property name=&quot;dataSource&quot; ref=&quot;dataSource&quot;/&gt;		&lt;/bean&gt;

整合后mybatis的使用原始dao方式配置mapper映射文件编写dao接口编写dao实现类（需要实现SqlSessionDaoSupport类）配置spring中bean，需要指定sqlSessionFactory&lt;bean id=&quot;userdao&quot; class=&quot;com.aly.dao.impl.UserDaoImpl&quot;&gt;			&lt;property name=&quot;sqlSessionFactory&quot; ref=&quot;sqlSessionFactory&quot;/&gt;		&lt;/bean&gt;mapper接口动态代理方式配置mapper映射文件编写dao接口配置spring中bean，需要指定sqlSessionFactory，mapperInterface属性&lt;bean id=&quot;userMapper&quot; class=&quot;org.mybatis.spring.mapper.MapperFactoryBean&quot;&gt;			&lt;property name=&quot;mapperInterface&quot; value=&quot;com.aly.mapper.UserMapper&quot;/&gt;			&lt;property name=&quot;sqlSessionFactory&quot; ref=&quot;sqlSessionFactory&quot;/&gt;		&lt;/bean&gt;ApplicationContext applicationContext = new 				ClassPathXmlApplicationContext(&quot;applicationContext.xml&quot;);				UserMapper userMapper = (UserMapper)applicationContext.getBean(&quot;userMapper&quot;);mapper接口动态代理（扫描方式）配置mapper映射文件编写dao接口配置spring中bean（只需要一次），需要指定basePackage，sqlSessionFactoryBeanName&lt;bean class=&quot;org.mybatis.spring.mapper.MapperScannerConfigurer&quot;&gt;			&lt;property name=&quot;basePackage&quot; value=&quot;com.aly.mapper&quot;/&gt;			&lt;property name=&quot;sqlSessionFactoryBeanName&quot; value=&quot;sqlSessionFactory&quot;/&gt;		&lt;/bean&gt;

Spring MVC介绍spring MVC是spring框架的一个模块，spring MVC和spring之间无需通过中间整合层进行整合（spring与mybatis需要mybatis-spring-1.2.2.jar）
spring MVC 框架并不知道使用的视图，所以不会强迫您只使用 JSP 技术。Spring MVC 分离了控制器、模型对象、分派器以及处理程序对象的角色，这种分离让它们更容易进行定制。
它是一个典型的教科书式的mvc构架，而不像struts等都是变种或者不是完全基于mvc系统的框架，对于初学者或者想了解mvc的人来说我觉得 spring是最好的，它的实现就是教科书！第二它和tapestry一样是一个纯正的servlet系统，这也是它和tapestry相比 struts所没有的优势。而且框架本身有代码，看起来容易理解。
工作原理用户request请求前端控制器DispatcherServlet
前端控制器通过处理器映射器HandlerMapping查找使哪一个处理器适配器HandlerAdapter（返回一个执行链）
前端控制器通过执行链请求处理器适配器HandlerAdapter
处理器适配器HandlerAdapter执行Handler处理器得到一个ModelAndView
将ModelAndView返回给前端控制器
前端控制器将ModelAndView发给视图解析器View resolver
view resolver解析后会返回一个纯view
将view返回给用户
springmvc配置文件&lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt;&lt;beans xmlns=&quot;http://www.springframework.org/schema/beans&quot;	xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot; 	xmlns:mvc=&quot;http://www.springframework.org/schema/mvc&quot;	xmlns:context=&quot;http://www.springframework.org/schema/context&quot;	xmlns:aop=&quot;http://www.springframework.org/schema/aop&quot; 	xmlns:tx=&quot;http://www.springframework.org/schema/tx&quot;	xsi:schemaLocation=&quot;http://www.springframework.org/schema/beans 		http://www.springframework.org/schema/beans/spring-beans-3.2.xsd 		http://www.springframework.org/schema/mvc 		http://www.springframework.org/schema/mvc/spring-mvc-3.2.xsd 		http://www.springframework.org/schema/context 		http://www.springframework.org/schema/context/spring-context-3.2.xsd 		http://www.springframework.org/schema/aop 		http://www.springframework.org/schema/aop/spring-aop-3.2.xsd 		http://www.springframework.org/schema/tx 		http://www.springframework.org/schema/tx/spring-tx-3.2.xsd &quot;&gt;&lt;/beans&gt;

配置前端控制器该配置信息在web.xml下配置
&lt;servlet&gt;		&lt;servlet-name&gt;springmvc&lt;/servlet-name&gt;		&lt;servlet-class&gt;org.springframework.web.servlet.DispatcherServlet&lt;/servlet-class&gt;		&lt;init-param&gt;				&lt;param-name&gt;contextConfigLocation&lt;/param-name&gt;			&lt;param-value&gt;classpath:springmvc.xml&lt;/param-value&gt;		&lt;/init-param&gt;	&lt;/servlet&gt;	&lt;servlet-mapping&gt;		&lt;servlet-name&gt;springmvc&lt;/servlet-name&gt;		&lt;url-pattern&gt;*.action&lt;/url-pattern&gt;	&lt;/servlet-mapping&gt;

配置处理器适配器&lt;bean class=&quot;org.springframework.web.servlet.mvc.SimpleControllerHandlerAdapter&quot;/&gt;通过上面代码，可在springmvc.xml中配置处理器适配器此适配器能执行实现 Controller接口的Handler。包在spring-webmvc-3.2.0.RELEASE.jar下

配置处理器映射器&lt;bean class=&quot;org.springframework.web.servlet.handler.BeanNameUrlHandlerMapping&quot;/&gt;通过上面代码，可在springmvc.xml中配置处理器映射器该配置可以将bean的name属性作为url进行查找，需要在配置Handler时指定name属性包在spring-webmvc-3.2.0.RELEASE.jar下

配置视图解析器&lt;bean class=&quot;org.springframework.web.servlet.view.InternalResourceViewResolver&quot;/&gt;通过上面代码，可在springmvc.xml中配置视图解析器该配置可以解析jsp，默认使用jstl标签，需要引入jstl的jar包包在spring-webmvc-3.2.0.RELEASE.jar下

配置处理器编写处理器，必须实现Controller接口必须实现接口里面handleRequest方法并指定返回的modelandview在springmvc中配置处理器，指定name属性用来访问，class属性文件位置&lt;bean name=&quot;/test.action&quot; class=&quot;com.aly.controller.TestController&quot;/&gt;

非注解的处理器映射器第一种org.springframework.web.servlet.handler.BeanNameUrlHandlerMapping第二种org.springframework.web.servlet.handler.SimpleUrlHandlerMapping多个处理器映射器可以并存，前端控制器判断url能被哪个处理器映射器映射，就让正确的处理器映射器映射。（了解）处理器映射器	&lt;bean class=&quot;org.springframework.web.servlet.handler.BeanNameUrlHandlerMapping&quot;/&gt;		处理器映射器  两个可以同时存在	&lt;bean class=&quot;org.springframework.web.servlet.handler.SimpleUrlHandlerMapping&quot;&gt;		&lt;property name=&quot;mappings&quot;&gt;			&lt;props&gt;				&lt;prop key=&quot;/test.action&quot;&gt;testCon&lt;/prop&gt;			&lt;/props&gt;		&lt;/property&gt;	&lt;/bean&gt; 

非注解的处理器适配器第一种org.springframework.web.servlet.mvc.SimpleControllerHandlerAdapter要求编写的Handler实现 Controller接口。第二种org.springframework.web.servlet.mvc.HttpRequestHandlerAdapter要求编写的Handler实现HttpRequestHandler接口。（方法里面实现和servlet一样） 处理器适配器	&lt;bean class=&quot;org.springframework.web.servlet.mvc.SimpleControllerHandlerAdapter&quot;/&gt; 处理器适配器	&lt;bean class=&quot;org.springframework.web.servlet.mvc.HttpRequestHandlerAdapter&quot;/&gt;

注解方式在spring3.1之前使用处理器映射器org.springframework.web.servlet.mvc.annotation.DefaultAnnotationHandlerMapping处理器适配器org.springframework.web.servlet.mvc.annotation.AnnotationMethodHandlerAdapter在spring3.1之后使用处理器映射器org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping处理器适配器org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerAdapter可由&lt;mvc:annotation-driven&gt;&lt;/mvc:annotation-driven&gt;代替（实际开发中也是应用此配置）

注解方式handler（处理器）的开发@Controller//使用Controller标识 它是一个控制器@RequestMapping(&quot;/test&quot;)//url映射可以与方法名不同（一般相同，规范）@Controllerpublic class Test2Con &#123;		@RequestMapping(&quot;/test.action&quot;)	public ModelAndView test()&#123;		ModelAndView mav = new ModelAndView();		mav.setViewName(&quot;index.jsp&quot;);		System.out.println(1111);		return mav;	&#125;

在spring中加载handler（处理器）第一种方式需要每个都加载一次&lt;bean class=&quot;com.aly.controller.Test2Con&quot;/&gt;第二种方式组件扫描（常用方式）统一加载一次性配置&lt;!-- 组件扫描方式加载控制器 --&gt;	&lt;context:component-scan base-package=&quot;com.aly.controller&quot; /&gt;
web工程加载spring配置文件
在web.xml文件加入如下代码，启动工程自动加载spring配置文件&lt;context-param&gt;		&lt;param-name&gt;contextConfigLocation&lt;/param-name&gt;		&lt;param-value&gt;/WEB-INF/classes/applicationContext.xml&lt;/param-value&gt;	&lt;/context-param&gt;	&lt;listener&gt;		&lt;listener-class&gt;org.springframework.web.context.ContextLoaderListener&lt;/listener-class&gt;	&lt;/listener&gt;&lt;!--加载mapper的，配置在spring配置文件中--&gt;&lt;bean class=&quot;org.mybatis.spring.mapper.MapperScannerConfigurer&quot;&gt;		&lt;property name=&quot;basePackage&quot; value=&quot;com.aly.mapper&quot;/&gt;		&lt;property name=&quot;sqlSessionFactoryBeanName&quot; value=&quot;sqlSessionFactory&quot;/&gt;	&lt;/bean&gt;

窄化请求路径@RequestMapping（）不仅可以放在方法上使用，用来确定路径，也可以用作Controller类上，那么访问时需要在方法基础之上再加一层目录，这样的访问方式叫窄化请求路径。访问路径：http://localhost:8080/test1/test3/test1.action@Controller@RequestMapping(&quot;/test3&quot;)public class Test3Con &#123;	@Autowired	UserMapper userMapper;	@RequestMapping(&quot;/test1.action&quot;)	public ModelAndView test()&#123;		ModelAndView mav = new ModelAndView();		User user = userMapper.selectByPrimaryKey(2);		//下一步操作等同于request.setAttribute();		mav.addObject(&quot;user&quot;,user);		mav.setViewName(&quot;/index.jsp&quot;);		return mav;	&#125;

视图解析器配置前缀、后缀为了简化jsp跳转url，视图解析器提供了两个参数，可以配置jsp访问url的前缀和后缀。&lt;bean class=&quot;org.springframework.web.servlet.view.InternalResourceViewResolver&quot;&gt;		&lt;!-- 视图前缀 --&gt;		&lt;property name=&quot;prefix&quot; value=&quot;&quot;/&gt;		&lt;!-- 视图后缀 --&gt;		&lt;property name=&quot;suffix&quot; value=&quot;&quot; /&gt;	&lt;/bean&gt;其中，第一个property的name属性为prefix ，规定jsp访问url的前缀，value里面为前缀内容。第二个property的name属性为suffix，规定jsp访问url的后缀，value里面为后缀内容，一般为.jsp。

Controller里面方法的返回值返回ModelAndView，需要在方法结束时，定义ModelAndView，将model和view分别进行设置。返回String，直接加视图名，需要在方法参数里面定义Model，在视图名前面加redirect:/forward:相当于重定向或转发。返回viod，需要在方法参数里面加HttpServletRequest或HttpServletResponse，也可一同时存在，相当于以前的servlet用法。

参数绑定默认支持的类型HttpServletRequestHttpServletResponseHttpSession简单类型（基本数据类型）通过@RequestParam对简单类型进行绑定。如果不使用@RequestParam，要求request传入参数名称和controller方法的形参名称一致，才能绑定成功。如果使用@RequestParam，不用限制request传入参数名称和controller方法的形参名称一致。domain类绑定参数需要页面中input的name和controller的pojo形参中的属性名称一致，才能将页面中数据绑定到domain对应的属性。（与简单类型互不影响）
字符集过滤器Spring的字符集过滤通常用于处理项目中的post乱码问题，该过滤器位于org.springframework.web.filter包中，指向类CharacterEncodingFilter。&lt;filter&gt;		&lt;filter-name&gt;CharacterEncodingFilter&lt;/filter-name&gt;		&lt;filter-class&gt;org.springframework.web.filter.CharacterEncodingFilter&lt;/filter-class&gt;		&lt;init-param&gt;			&lt;param-name&gt;encoding&lt;/param-name&gt;			&lt;param-value&gt;UTF-8&lt;/param-value&gt;		&lt;/init-param&gt;	&lt;/filter&gt;	&lt;filter-mapping&gt;		&lt;filter-name&gt;CharacterEncodingFilter&lt;/filter-name&gt;		&lt;url-pattern&gt;/*&lt;/url-pattern&gt;	&lt;/filter-mapping&gt;

文件上传复制所需jar包到工程lib目录下commons-io-2.3.jar在spring配置文件中加入如下代码&lt;bean id=&quot;multipartResolver&quot;        class=&quot;org.springframework.web.multipart.commons.CommonsMultipartResolver&quot;&gt;        &lt;!-- 设置编码 --&gt;        &lt;property name=&quot;defaultEncoding&quot; value=&quot;UTF-8&quot; /&gt;        &lt;!-- 设置上传文件总大小 --&gt;        &lt;property name=&quot;maxUploadSize&quot; value=&quot;10240000&quot; /&gt;        &lt;!-- 设置单个上传文件大小 --&gt;        &lt;property name=&quot;maxUploadSizePerFile&quot; value=&quot;102400&quot; /&gt;    &lt;/bean&gt;创建上传页面Method必须是post必须配置enctype的值为multipart/form-data&lt;form action=&quot;test/upload.action&quot; method=&quot;post&quot;        enctype=&quot;multipart/form-data&quot;&gt;        &lt;input type=&quot;file&quot; name=&quot;uploadFile&quot; value=&quot;选择文件&quot; /&gt;         &lt;input type=&quot;submit&quot;value=&quot;提交&quot; /&gt;&lt;/form&gt;创建上传用的controller@RequestMapping(&quot;/upload.action&quot;)	public String upload(Model model,HttpSession session, MultipartFile uploadFile)            throws Exception &#123;		        String originalFilename = uploadFile.getOriginalFilename();        System.out.println(originalFilename);                String name = originalFilename.substring(originalFilename.lastIndexOf(&quot;.&quot;));        UUID uuid = UUID.randomUUID();        String url = session.getServletContext().getRealPath(&quot;/upload/&quot;)+uuid+name;        System.out.println(uuid+name);        if (uploadFile.getSize() &gt; 0) &#123;                File realPath = new File(&quot;d:/&quot;,uuid+name);                System.out.println(realPath.getPath());                uploadFile.transferTo(realPath);            &#125;        model.addAttribute(&quot;url&quot;,uuid+name);        return &quot;/index.jsp&quot;;    &#125;

以下代码实现javascript读取txt文件打印到浏览器中
function load(name) &#123;        let xhr = new XMLHttpRequest(),            okStatus = document.location.protocol === &quot;file:&quot; ? 0 : 200;        xhr.open(&#x27;GET&#x27;, name, false);        xhr.overrideMimeType(&quot;text/html;charset=utf-8&quot;);//默认为utf-8        xhr.send(null);        return xhr.status === okStatus ? xhr.responseText : null;&#125;let text = load(&quot;文件名.txt&quot;);console.log(text);  //输出到浏览器控制器中 //document.write(text);  //打印在网页中 //document.write(&quot;&lt;pre&gt;&quot;+text+&quot;&lt;pre/&gt;&quot;)//解决txt的换行无法打印到网页上的问题


预览&emsp;&emsp;下载








//读取txt文件
function load(name) {    
    let xhr = new XMLHttpRequest(),        
    okStatus = document.location.protocol === "file:" ? 0 : 200;    
    xhr.open('GET', name, false);    
    xhr.overrideMimeType("text/html;charset=utf-8");//默认为utf-8    
    xhr.send(null);    
    return xhr.status === okStatus ? xhr.responseText : null;
}
function show(){
    let text = load("tv.txt");
    //console.log(text);  //输出到浏览器控制器中 
    //document.write(text);  //打印在网页中 
    //document.write(""+text+"")//解决txt的换行无法打印到网页上的问题
    document.getElementById("show").innerHTML=text;
}

jdbc连接数据库存在的问题数据库链接创建、释放频繁造成系统资源浪费从而影响系统性能，如果使用数据库链接池可解决此问题。 Sql语句在代码中硬编码，造成代码不易维护，实际应用sql变化的可能较大，sql变动需要改变java代码。 使用preparedStatement向占有位符号传参数存在硬编码，因为sql语句的where条件不一定，可能多也可能少，修改sql还要修改代码，系统不易维护。 对结果集解析存在硬编码（查询列名），sql变化导致解析代码变化，系统不易维护，如果能将数据库记录封装成pojo对象解析比较方便。 mybatis介绍MyBatis 本是apache的一个开源项目iBatis, 2010年这个项目由apache software foundation 迁移到了google code，并且改名为MyBatis，实质上Mybatis对ibatis进行一些改进。 MyBatis是一个优秀的持久层框架，它对jdbc的操作数据库的过程进行封装，使开发者只需要关注 SQL 本身，而不需要花费精力去处理例如注册驱动、创建connection、创建statement、手动设置参数、结果集检索等jdbc繁杂的过程代码。 Mybatis通过xml或注解的方式将要执行的各种statement（statement、preparedStatemnt、CallableStatement）配置起来，并通过java对象和statement中的sql进行映射生成最终执行的sql语句，最后由mybatis框架执行sql并将结果映射成java对象并返回。 mybatis环境搭建加入mybatis核心包、依赖包、数据驱动包。maven（jar包） asm、cglib、commons-logging、javassist、junit、log4j、log4j-api、log4j-core、mybatis、mysql-connector-java、slf4j-api、slf4j-log4j12
配置log4j，src下创建log4j.properties # Global logging configurationlog4j.rootLogger=DEBUG, stdout# Console output...log4j.appender.stdout=org.apache.log4j.ConsoleAppenderlog4j.appender.stdout.layout=org.apache.log4j.PatternLayoutlog4j.appender.stdout.layout.ConversionPattern=%5p [%t] - %m%n SqlMapConfig.xml基础配置SqlMapConfig.xml是mybatis核心配置文件，下面文件的配置内容为数据源、事务管理。 &lt;!DOCTYPE configuration PUBLIC &quot;-//mybatis.org//DTD Config 3.0//EN&quot; &quot;http://mybatis.org/dtd/mybatis-3-config.dtd&quot;&gt; &lt;configuration&gt; &lt;!-- 和spring整合后 environments配置将废除 数据源--&gt; &lt;environments default=&quot;development&quot;&gt; &lt;environment id=&quot;development&quot;&gt; &lt;!-- 使用jdbc事务管理,事务控制由mybatis管理--&gt; &lt;transactionManager type=&quot;JDBC&quot; /&gt; &lt;!-- 数据库连接池,由mybatis管理--&gt; &lt;dataSource type=&quot;POOLED&quot;&gt; &lt;property name=&quot;driver&quot; value=&quot;com.mysql.jdbc.Driver&quot; /&gt; &lt;property name=&quot;url&quot; value=&quot;jdbc:mysql://localhost:3306/aa&quot; /&gt; &lt;property name=&quot;username&quot; value=&quot;root&quot; /&gt; &lt;property name=&quot;password&quot; value=&quot;&quot; /&gt; &lt;/dataSource&gt; &lt;/environment&gt; &lt;/environments&gt;&lt;/configuration&gt; 创建mapper映射文件创建pojo模型，创建映射文件，映射文件基础配置如下： &lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot; ?&gt;&lt;!DOCTYPE mapper PUBLIC &quot;-//mybatis.org//DTD Mapper 3.0//EN&quot; &quot;http://mybatis.org/dtd/mybatis-3-mapper.dtd&quot; &gt;&lt;!-- namespace命名空间 用来区分不同的mapper --&gt;&lt;mapper namespace=&quot;test&quot;&gt;&lt;/mapper&gt; 其中namespace为命名空间，用于隔离sql语句。加入以下代码完成查询配置 &lt;!-- select 查询标签 需要 返回类类型resultType parameterType代表输入类型（可选）--&gt; &lt;select id=&quot;selUserById&quot; parameterType=&quot;int&quot; resultType=&quot;cn.com.aly.po.User&quot;&gt; select * from user where id = #&#123;id&#125; &lt;/select&gt; 在SqlMapConfig.xml中加载映射文件&lt;!-- 配置映射文件 --&gt; &lt;mappers&gt; &lt;mapper resource=&quot;cn/com/aly/mapper/UserMapper.xml&quot; /&gt; &lt;/mappers&gt;将上面代码加到SqlMapConfig.xml的&lt;configuration&gt;标签下 执行查询操作//获取配置文件String resource = new String(&quot;SqlMapConfig.xml&quot;);//获取配置文件输入流InputStream inputStream = Resources.getResourceAsStream(resource);//创建SqlSessionFactory（sql会话工厂）SqlSessionFactory sqlSessionFactory = new SqlSessionFactoryBuilder().build(inputStream);//通过工厂的到sqlsession（会话）SqlSession sqlSession = sqlSessionFactory.openSession();执行查询--&gt;关闭会话Stu stu = sqlSession.selectOne(&quot;test.selUserById&quot;, 1); System.out.println(stu); sqlSession.close(); #{}与${}的区别#{}表示一个占位符号，通过#{}可以实现preparedStatement向占位符中设置值，自动进行java类型和jdbc类型转换，#{}可以有效防止sql注入。 #{}可以接收简单类型值或pojo属性值。 如果parameterType传输单个简单类型值，#{}括号中可以是value或其它名称。 ${}表示拼接sql串，通过${}可以将parameterType 传入的内容拼接在sql中且不进行jdbc类型转换， ${}可以接收简单类型值或pojo属性值，如果parameterType传输单个简单类型值，${}括号中只能是value。 Mybatis增删改添加一条数据&lt;insert id=&quot;addUser&quot; parameterType=&quot;cn.com.aly.po.User&quot;&gt; insert into user(username,pwd,sex,age) values(#&#123;username&#125;,#&#123;pwd&#125;,#&#123;sex&#125;,#&#123;age&#125;)&lt;/insert&gt;添加一条数据并返回主键&lt;selectKey keyProperty=&quot;id&quot; order=&quot;AFTER&quot; resultType=&quot;int&quot;&gt; select last_insert_id()&lt;/selectKey&gt;sqlSession.insert(&quot;insertStu&quot;, stu);//执行插入删除一条数据&lt;delete id=&quot;delUserById&quot; parameterType=&quot;cn.com.aly.po.User&quot;&gt; delete from user where id = #&#123;id&#125;&lt;/delete&gt;User user = new User();user.setId(29);int i = sqlSession.delete(&quot;test.delUserById&quot;, user);sqlSession.commit();sqlSession.close();修改一条数据&lt;update id=&quot;updUserById&quot; parameterType=&quot;cn.com.aly.po.User&quot;&gt; update user set username=#&#123;username&#125;,pwd = #&#123;pwd&#125;,sex = #&#123;sex&#125;,age=#&#123;age&#125; where id=#&#123;id&#125;&lt;/update&gt;User user = new User();user.setId(28);user.setUsername(&quot;uuqq&quot;);user.setPwd(&quot;123&quot;);user.setSex(&quot;男&quot;);user.setAge(23);int i = sqlSession.update(&quot;test.updUserById&quot;, user); 原始dao开发编写dao接口（开发中直接提交到版本控制服务器上，其他人可继续开发）编写dao实现类，实现dao里面的方法，完成功能开发原始dao开发中存在以下问题Dao方法体存在重复代码：通过SqlSessionFactory创建SqlSession，调用SqlSession的数据库操作方法调用sqlSession的数据库操作方法需要指定statement的id，这里存在硬编码，不得于开发维护。 mapper动态代理Mapper接口开发方法只需要程序员编写Mapper接口（相当于Dao接口），由Mybatis框架根据接口定义创建接口的动态代理对象，代理对象的方法体同上边Dao接口实现类方法。（也就是说不需要写实现类） 但Mapper接口开发必需遵循以下规范：&#x2F;&#x2F;sqlSession.getMapper（）; 1、Mapper.xml文件中的namespace与mapper接口的类路径相同。 2、Mapper接口方法名和Mapper.xml中定义的每个statement的id相同 3、Mapper接口方法的输入参数类型和mapper.xml中定义的每个sql 的parameterType的类型相同 4、Mapper接口方法的输出参数类型和mapper.xml中定义的每个sql的resultType的类型相同 动态sql-ifif为select标签下子标签表示判断，属性test表示判断条件&lt;select id=&quot;selUserByName&quot; parameterType=&quot;cn.com.aly.po.User&quot; resultType=&quot;cn.com.aly.po.User&quot;&gt; select * from user Where 1=1 &lt;if test=&quot;username != null and username!=&#x27;&#x27;&quot;&gt; and username = #&#123;username&#125; &lt;/if&gt; &lt;if test=&quot;sex != null and sex!=&#x27;&#x27;&quot;&gt; and sex = #&#123;sex&#125; &lt;/if&gt;&lt;/select&gt; 动态sql-wherewhere为select标签下子标签，用来表示条件&lt;select id=&quot;selUserByName&quot; parameterType=&quot;cn.com.aly.po.User&quot; resultType=&quot;cn.com.aly.po.User&quot;&gt; select * from user &lt;where&gt; &lt;if test=&quot;username != null and username!=&#x27;&#x27;&quot;&gt; and username = #&#123;username&#125; &lt;/if&gt; &lt;if test=&quot;sex != null and sex!=&#x27;&#x27;&quot;&gt; and sex = #&#123;sex&#125; &lt;/if&gt; &lt;/where&gt;&lt;/select&gt;会自动处理掉第一个if里面加的and sql片段Sql中可将重复的sql提取出来，使用时用include引用即可，最终达到sql重用的目的，如下&lt;!-- 定义sql片段 --&gt; &lt;sql id=&quot;userwhere&quot;&gt; &lt;if test=&quot;id != null and id !=&#x27;&#x27;&quot;&gt; and id = #&#123;id&#125; &lt;/if&gt; &lt;if test=&quot;username != null and username !=&#x27;&#x27;&quot;&gt; and username = #&#123;username&#125; &lt;/if&gt; &lt;if test=&quot;pwd != null and pwd !=&#x27;&#x27;&quot;&gt; and pwd = #&#123;pwd&#125; &lt;/if&gt; &lt;if test=&quot;sex != null and sex !=&#x27;&#x27;&quot;&gt; and sex=#&#123;sex&#125; &lt;/if&gt; &lt;if test=&quot;addr != null and addr !=&#x27;&#x27;&quot;&gt; and addr=#&#123;addr&#125; &lt;/if&gt; &lt;if test=&quot;photo != null and photo !=&#x27;&#x27;&quot;&gt; and photo=#&#123;photo&#125; &lt;/if&gt; &lt;if test=&quot;hobby != null and hobby !=&#x27;&#x27;&quot;&gt; and hobby=#&#123;hobby&#125; &lt;/if&gt; &lt;/sql&gt;&lt;select id=&quot;selUser&quot; parameterType=&quot;cn.com.aly.po.Userinfo&quot; resultType=&quot;cn.com.aly.po.Userinfo&quot;&gt; select * from userinfo &lt;where&gt; &lt;!-- 引用sql片段 --&gt; &lt;include refid=&quot;userwhere&quot; /&gt; &lt;/where&gt;&lt;/select&gt; 高级映射一对一首先确定sql语句，确定要查询的列 根据sql语句完成扩展domain类的建立，继承主domain类，将查询的列中不包含在主类中的列名加到扩展domain类中 映射文件输出类型为扩展domain类 定义mapper接口中方法 Sql语句 SELECT o.*,u.username,u.pwd,u.sex,u.age FROM orders o,USER u WHERE o.user_id = u.id AND o.id = 1 定义pojo扩展类 public class OrdersCustem extends Orders &#123; private String username; private String pwd; private String sex; private Integer age;
确定返回类型 resultType=&quot;cn.com.aly.po.OrdersCustem&quot;
定义mapper接口中方法 OrdersCustem selOrdersWithUserById(Orders orders); 高级映射一对多首先确定sql语句，确定要查询的列，并将多方创建成list放入一方 根据sql语句完成resultMap的建立，association为一对一的配置，collection为一对多，多方配置 映射文件输出使用resultMap，并将值设置为刚建立的resultMap的id 定义mapper接口中方法 sql语句SELECT o.*,u.username,u.pwd,u.sex,u.age FROM orders o,USER u WHERE o.user_id = u.id AND u.id = #&#123;id&#125; 创建resultMap &lt;!-- id ：下面使用到该resultMap的时候所写的值 type规定当前类是那一个 --&gt; &lt;resultMap id=&quot;resultofuser&quot; type=&quot;cn.com.aly.po.User&quot;&gt; &lt;id property=&quot;id&quot; column=&quot;user_id&quot;/&gt; &lt;result property=&quot;username&quot; column=&quot;username&quot;/&gt; &lt;result property=&quot;pwd&quot; column=&quot;pwd&quot;/&gt; &lt;result property=&quot;sex&quot; column=&quot;sex&quot;/&gt; &lt;result property=&quot;age&quot; column=&quot;age&quot;/&gt; &lt;!-- 一对多时 多方的配置 ofType配置的是多方的类型 --&gt; &lt;collection property=&quot;orderList&quot; ofType=&quot;cn.com.aly.po.Orders&quot;&gt; &lt;id property=&quot;id&quot; column=&quot;id&quot;/&gt; &lt;result property =&quot;user_id&quot; column=&quot;user_id&quot;/&gt; &lt;result property =&quot;number&quot; column=&quot;number&quot;/&gt; &lt;result property =&quot;createtime&quot; column=&quot;createtime&quot;/&gt; &lt;result property =&quot;note&quot; column=&quot;note&quot;/&gt; &lt;/collection&gt; &lt;/resultMap&gt;
确定返回类型 resultMap=&quot;resultofuser&quot;
定义mapper接口中方法 User selUserWithOrdersById(User user); 高级映射多对多多对多映射实质为：一对一与一对多的整合，同样使用resultMap，灵活使用association和collection。 association将关联查询信息映射到一个pojo对象中。 collection将关联查询信息映射到一个list集合中。 注意：如果使用resultType则无法关联查询 高级映射延迟加载需要查询关联信息时，使用mybatis延迟加载特性可有效的减少数据库压力，首次查询只查询主要信息，关联信息等用户获取时再加载。
设置项 描述 允许值 默认值
lazyLoadingEnabled 全局性设置懒加载。如果设为‘false’，则所有相关联的都会被初始化加载 true、false false
aggressiveLazyLoading 当设置为‘true’的时候，懒加载的对象可能被任何懒属性全部加载。否则，每个属性都按需加载 true、false true
&lt;settings&gt; &lt;setting name=&quot;lazyLoadingEnabled&quot; value=&quot;true&quot;/&gt; &lt;setting name=&quot;aggressiveLazyLoading&quot; value=&quot;false&quot;/&gt;&lt;/settings&gt; 应用时需要在association或collection指定javaType（关联结果映射位置），select（指定关联查询sql），column（需要传入的值） &lt;resultMap id=&quot;resultforlazy&quot; type=&quot;cn.com.aly.po.Orders&quot;&gt; &lt;id property=&quot;id&quot; column=&quot;id&quot;/&gt; &lt;result property =&quot;user_id&quot; column=&quot;user_id&quot;/&gt; &lt;result property =&quot;number&quot; column=&quot;number&quot;/&gt; &lt;result property =&quot;createtime&quot; column=&quot;createtime&quot;/&gt; &lt;result property =&quot;note&quot; column=&quot;note&quot;/&gt; &lt;association property=&quot;user&quot; javaType=&quot;cn.com.aly.po.User&quot; select=&quot;selUserById&quot; column=&quot;user_id&quot;&gt; &lt;id property=&quot;id&quot; column=&quot;user_id&quot;/&gt; &lt;result property=&quot;username&quot; column=&quot;username&quot;/&gt; &lt;result property=&quot;pwd&quot; column=&quot;pwd&quot;/&gt; &lt;result property=&quot;sex&quot; column=&quot;sex&quot;/&gt; &lt;result property=&quot;age&quot; column=&quot;age&quot;/&gt; &lt;/association&gt;&lt;/resultMap&gt;

分享一个MySQL（Oracle）数据库sql练习

表结构CREATE TABLE STUDENT(SNO VARCHAR(3) NOT NULL,SNAME VARCHAR(4) NOT NULL,SSEX VARCHAR(2) NOT NULL,SBIRTHDAY DATETIME,CLASS VARCHAR(5));CREATE TABLE COURSE(CNO VARCHAR(5) NOT NULL,CNAME VARCHAR(10) NOT NULL,TNO VARCHAR(10) NOT NULL);CREATE TABLE SCORE(SNO VARCHAR(3) NOT NULL,CNO VARCHAR(5) NOT NULL,DEGREE NUMERIC(10, 1) NOT NULL);CREATE TABLE TEACHER(TNO VARCHAR(3) NOT NULL,TNAME VARCHAR(4) NOT NULL, TSEX VARCHAR(2) NOT NULL,TBIRTHDAY DATETIME NOT NULL, PROF VARCHAR(6),DEPART VARCHAR(10) NOT NULL);INSERT INTO STUDENT (SNO,SNAME,SSEX,SBIRTHDAY,CLASS) VALUES (108 ,&#x27;曾华&#x27;,&#x27;男&#x27; ,&#x27;1977-09-01&#x27;,95033);INSERT INTO STUDENT (SNO,SNAME,SSEX,SBIRTHDAY,CLASS) VALUES (105 ,&#x27;匡明&#x27;,&#x27;男&#x27; ,&#x27;1975-10-02&#x27;,95031);INSERT INTO STUDENT (SNO,SNAME,SSEX,SBIRTHDAY,CLASS) VALUES (107 ,&#x27;王丽&#x27;,&#x27;女&#x27; ,&#x27;1976-01-23&#x27;,95033);INSERT INTO STUDENT (SNO,SNAME,SSEX,SBIRTHDAY,CLASS) VALUES (101 ,&#x27;李军&#x27;,&#x27;男&#x27; ,&#x27;1976-02-20&#x27;,95033);INSERT INTO STUDENT (SNO,SNAME,SSEX,SBIRTHDAY,CLASS) VALUES (109 ,&#x27;王芳&#x27;,&#x27;女&#x27; ,&#x27;1975-02-10&#x27;,95031);INSERT INTO STUDENT (SNO,SNAME,SSEX,SBIRTHDAY,CLASS) VALUES (103 ,&#x27;陆君&#x27;,&#x27;男&#x27; ,&#x27;1974-06-03&#x27;,95031);INSERT INTO COURSE(CNO,CNAME,TNO)VALUES (&#x27;3-105&#x27; ,&#x27;计算机导论&#x27;,825);INSERT INTO COURSE(CNO,CNAME,TNO)VALUES (&#x27;3-245&#x27; ,&#x27;操作系统&#x27; ,804);INSERT INTO COURSE(CNO,CNAME,TNO)VALUES (&#x27;6-166&#x27; ,&#x27;数据电路&#x27; ,856);INSERT INTO COURSE(CNO,CNAME,TNO)VALUES (&#x27;9-888&#x27; ,&#x27;高等数学&#x27; ,100);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (103,&#x27;3-245&#x27;,86);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (105,&#x27;3-245&#x27;,75);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (109,&#x27;3-245&#x27;,68);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (103,&#x27;3-105&#x27;,92);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (105,&#x27;3-105&#x27;,88);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (109,&#x27;3-105&#x27;,76);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (101,&#x27;3-105&#x27;,64);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (107,&#x27;3-105&#x27;,91);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (108,&#x27;3-105&#x27;,78);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (101,&#x27;6-166&#x27;,85);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (107,&#x27;6-106&#x27;,79);INSERT INTO SCORE(SNO,CNO,DEGREE)VALUES (108,&#x27;6-166&#x27;,81);INSERT INTO TEACHER(TNO,TNAME,TSEX,TBIRTHDAY,PROF,DEPART)VALUES (804,&#x27;李诚&#x27;,&#x27;男&#x27;,&#x27;1958-12-02&#x27;,&#x27;副教授&#x27;,&#x27;计算机系&#x27;);INSERT INTO TEACHER(TNO,TNAME,TSEX,TBIRTHDAY,PROF,DEPART)VALUES (856,&#x27;张旭&#x27;,&#x27;男&#x27;,&#x27;1969-03-12&#x27;,&#x27;讲师&#x27;,&#x27;电子工程系&#x27;);INSERT INTO TEACHER(TNO,TNAME,TSEX,TBIRTHDAY,PROF,DEPART)VALUES (825,&#x27;王萍&#x27;,&#x27;女&#x27;,&#x27;1972-05-05&#x27;,&#x27;助教&#x27;,&#x27;计算机系&#x27;);INSERT INTO TEACHER(TNO,TNAME,TSEX,TBIRTHDAY,PROF,DEPART)VALUES (831,&#x27;刘冰&#x27;,&#x27;女&#x27;,&#x27;1977-08-14&#x27;,&#x27;助教&#x27;,&#x27;电子工程系&#x27;);
题目1、 查询Student表中的所有记录的Sname、Ssex和Class列。select sname,ssex,class from student2、 查询教师所有的单位即不重复的Depart列。select DISTINCT depart from teacher3、 查询Student表的所有记录。Select * from student4、 查询Score表中成绩在60到80之间的所有记录。select * from score where degree between 60 and 805、 查询Score表中成绩为85，86或88的记录。select * from score where degree=85UNION select * from score where degree=86union select * from score where degree=886、 查询Student表中“95031”班或性别为“女”的同学记录。select * from student where class =&#x27;95031&#x27; or ssex=&#x27;女&#x27;7、 以Class降序查询Student表的所有记录。select * from student order by class DESC8、 以Cno升序、Degree降序查询Score表的所有记录。select * from score order by cno asc select * from score order by Degree DESC9、 查询“95031”班的学生人数。select count(*) from student where class=&#x27;95031&#x27;10、查询Score表中的最高分的学生学号和课程号。11、查询‘3-105’号课程的平均分。12、查询Score表中至少有5名学生选修的并以3开头的课程的平均分数。13、查询最低分大于70，最高分小于90的Sno列。14、查询所有学生的Sname、Cno和Degree列。15、查询所有学生的Sno、Cname和Degree列。16、查询所有学生的Sname、Cname和Degree列。17、查询“95033”班所选课程的平均分。18、假设使用如下命令建立了一个grade表：create table grade(low   int,upp   number(3),rank   char(1));insert into grade values(90,100,&#x27;A&#x27;);insert into grade values(80,89,&#x27;B&#x27;);insert into grade values(70,79,&#x27;C&#x27;);insert into grade values(60,69,&#x27;D&#x27;);insert into grade values(0,59,&#x27;E&#x27;);commit;现查询所有同学的Sno、Cno和rank列。19、查询选修“3-105”课程的成绩高于“109”号同学成绩的所有同学的记录。20、查询score中选学一门以上课程的同学中分数为非最高分成绩的记录。21、查询成绩高于学号为“109”、课程号为“3-105”的成绩的所有记录。22、查询和学号为108的同学同年出生的所有学生的Sno、Sname和Sbirthday列。23、查询“张旭“教师任课的学生成绩。24、查询选修某课程的同学人数多于5人的教师姓名。25、查询95033班和95031班全体学生的记录。26、查询存在有85分以上成绩的课程Cno.27、查询出“计算机系“教师所教课程的成绩表。28、查询“计算机系”与“电子工程系“不同职称的教师的Tname和Prof。29、查询选修编号为“3-105“课程且成绩至少高于选修编号为“3-245”的同学的Cno、Sno和Degree,并按Degree从高到低次序排序。30、查询选修编号为“3-105”且成绩高于选修编号为“3-245”课程的同学的Cno、Sno和Degree.31、查询所有教师和同学的name、sex和birthday.32、查询所有“女”教师和“女”同学的name、sex和birthday.33、查询成绩比该课程平均成绩低的同学的成绩表。34、查询所有任课教师的Tname和Depart.35  查询所有未讲课的教师的Tname和Depart. 36、查询至少有2名男生的班号。37、查询Student表中不姓“王”的同学记录。38、查询Student表中每个学生的姓名和年龄。39、查询Student表中最大和最小的Sbirthday日期值。40、以班号和年龄从大到小的顺序查询Student表中的全部记录。41、查询“男”教师及其所上的课程。42、查询最高分同学的Sno、Cno和Degree列。43、查询和“李军”同性别的所有同学的Sname.44、查询和“李军”同性别并同班的同学Sname.45、查询所有选修“计算机导论”课程的“男”同学的成绩表
参考答案一1. SELECT SNAME,SSEX,CLASS FROM STUDENT;2. SELECT DISTINCT DEPART FROM TEACHER;3. SELECT * FROM STUDENT;4. SELECT * FROM SCORE WHERE DEGREE BETWEEN 60 AND 80;5.SELECT * FROM SCORE WHERE DEGREE IN (85,86,88);6. SELECT * FROM STUDENT WHERE CLASS=&#x27;95031&#x27; OR SSEX=&#x27;女&#x27;;7.SELECT * FROM STUDENT ORDER BY CLASS DESC;8.SELECT * FROM SCORE ORDER BY CNO ASC,DEGREE DESC;9.SELECT  COUNT(*) FROM STUDENT WHERE CLASS=&#x27;95031&#x27;;10.SELECT SNO,CNO FROM SCORE WHERE DEGREE=(SELECT MAX(DEGREE) FROM SCORE);SELECT SNO,CNO FROM SCORE ORDER BY DEGREE DESC LIMIT 1;11.SELECT AVG(DEGREE) FROM SCORE WHERE CNO=&#x27;3-105&#x27;;12.select avg(degree),cnofrom scorewhere cno like &#x27;3%&#x27;group by cnohaving count(sno)&gt;= 5;13.SELECT SNO FROM SCORE GROUP BY SNO HAVING MIN(DEGREE)&gt;70 AND MAX(DEGREE)&lt;90;14.SELECT A.SNAME,B.CNO,B.DEGREE FROM STUDENT AS A JOIN SCORE AS B ON A.SNO=B.SNO;15.SELECT A.CNAME, B.SNO,B.DEGREE FROM COURSE AS A JOIN SCORE AS B ON A.CNO=B.CNO ;16.SELECT A.SNAME,B.CNAME,C.DEGREE FROM STUDENT A JOIN (COURSE B,SCORE C)ON A.SNO=C.SNO AND B.CNO =C.CNO;17.SELECT AVG(A.DEGREE) FROM SCORE A JOIN STUDENT B ON A.SNO = B.SNO WHERE B.CLASS=&#x27;95033&#x27;;18.SELECT A.SNO,A.CNO,B.RANK FROM SCORE A,GRADE B WHERE A.DEGREE BETWEEN B.LOW AND B.UPP ORDER BY RANK;19.SELECT A.* FROM SCORE A JOIN SCORE B WHERE A.CNO=&#x27;3-105&#x27; AND A.DEGREE&gt;B.DEGREE AND B.SNO=&#x27;109&#x27; AND B.CNO=&#x27;3-105&#x27;;另一解法：SELECT A.* FROM SCORE A  WHERE A.CNO=&#x27;3-105&#x27; AND A.DEGREE&gt;ALL(SELECT DEGREE FROM SCORE B WHERE B.SNO=&#x27;109&#x27; AND B.CNO=&#x27;3-105&#x27;);20.SELECT * FROM score s WHERE DEGREE&lt;(SELECT MAX(DEGREE) FROM SCORE) GROUP BY SNO HAVING COUNT(SNO)&gt;1 ORDER BY DEGREE ;21.见19的第二种解法22.SELECT SNO,SNAME,SBIRTHDAY FROM STUDENT WHERE YEAR(SBIRTHDAY)=(SELECT YEAR(SBIRTHDAY) FROM STUDENT WHERE SNO=&#x27;108&#x27;);Oracle:select x.cno,x.Sno,x.degree from score x,score y where x.degree&gt;y.degree and y.sno=&#x27;109&#x27;and y.cno=&#x27;3-105&#x27;;select cno,sno,degree from score   where degree &gt;(select degree from score where sno=&#x27;109&#x27; and cno=&#x27;3-105&#x27;)23.SELECT A.SNO,A.DEGREE FROM SCORE A JOIN (TEACHER B,COURSE C)ON A.CNO=C.CNO AND B.TNO=C.TNOWHERE B.TNAME=&#x27;张旭&#x27;;另一种解法：select cno,sno,degree from score where cno=(select x.cno from course x,teacher y where x.tno=y.tno and y.tname=&#x27;张旭&#x27;);根据实际EXPLAIN此SELECT语句，第一个的扫描次数要小于第二个24.SELECT A.TNAME FROM TEACHER A JOIN (COURSE B, SCORE C) ON (A.TNO=B.TNO AND B.CNO=C.CNO) GROUP BY C.CNO HAVING COUNT(C.CNO)&gt;5;另一种解法：select tname from teacher where tno in(select x.tno from course x,score y where x.cno=y.cno group by x.tno having count(x.tno)&gt;5);实际测试1明显优于225.select cno,sno,degree from score where cno=(select x.cno from course x,teacher y where x.tno=y.tno and y.tname=&#x27;张旭&#x27;);26.SELECT CNO FROM SCORE GROUP BY CNO HAVING MAX(DEGREE)&gt;85;另一种解法：select distinct cno from score where degree in (select degree from score where degree&gt;85);27.SELECT A.* FROM SCORE A JOIN (TEACHER B,COURSE C) ON A.CNO=C.CNO AND B.TNO=C.TNOWHERE B.DEPART=&#x27;计算机系&#x27;;另一种解法：SELECT * from score where cno in (select a.cno from course a join teacher b on a.tno=b.tno and b.depart=&#x27;计算机系&#x27;);此时2略好于1，在多连接的境况下性能会迅速下降28.select tname,prof from teacher where depart=&#x27;计算机系&#x27; and prof not in (select prof from teacher where depart=&#x27;电子工程系&#x27;);29.SELECT * FROM SCORE WHERE DEGREE&gt;ANY(SELECT DEGREE FROM SCORE WHERE CNO=&#x27;3-245&#x27;) ORDER BY DEGREE DESC;30.SELECT * FROM SCORE WHERE DEGREE&gt;ALL(SELECT DEGREE FROM SCORE WHERE CNO=&#x27;3-245&#x27;) ORDER BY DEGREE DESC;31.SELECT SNAME AS NAME, SSEX AS SEX, SBIRTHDAY AS BIRTHDAY FROM STUDENTUNIONSELECT TNAME AS NAME, TSEX AS SEX, TBIRTHDAY AS BIRTHDAY FROM TEACHER;32.SELECT SNAME AS NAME, SSEX AS SEX, SBIRTHDAY AS BIRTHDAY FROM STUDENT WHERE SSEX=&#x27;女&#x27;UNIONSELECT TNAME AS NAME, TSEX AS SEX, TBIRTHDAY AS BIRTHDAY FROM TEACHER WHERE TSEX=&#x27;女&#x27;;33.SELECT A.* FROM SCORE A WHERE DEGREE&lt;(SELECT AVG(DEGREE) FROM SCORE B WHERE A.CNO=B.CNO);须注意********此题34.解法一：SELECT A.TNAME,A.DEPART FROM TEACHER A JOIN COURSE B ON A.TNO=B.TNO;解法二：select tname,depart from teacher a where exists(select * from course b where a.tno=b.tno);解法三：SELECT TNAME,DEPART FROM TEACHER WHERE TNO IN (SELECT TNO FROM COURSE);实际分析，第一种揭发貌似更好，至少扫描次数最少。35.解法一：SELECT TNAME,DEPART FROM TEACHER A LEFT JOIN COURSE B USING(TNO) WHERE ISNUL(B.tno);解法二：select tname,depart from teacher a where not exists(select * from course b where a.tno=b.tno);解法三：SELECT TNAME,DEPART FROM TEACHER WHERE TNO NOT IN (SELECT TNO FROM COURSE);NOT IN的方法效率最差，其余两种差不多36.SELECT CLASS FROM STUDENT A WHERE SSEX=&#x27;男&#x27; GROUP BY CLASS HAVING COUNT(SSEX)&gt;1;37.SELECT * FROM STUDENT A WHERE SNAME not like &#x27;王%&#x27;;38.SELECT SNAME,(YEAR(NOW())-YEAR(SBIRTHDAY)) AS AGE FROM STUDENT;39.select sname,sbirthday as THEMAX from student where sbirthday =(select min(SBIRTHDAY) from student)unionselect sname,sbirthday as THEMIN from student where sbirthday =(select max(SBIRTHDAY) from student);40.SELECT CLASS,(YEAR(NOW())-YEAR(SBIRTHDAY)) AS AGE FROM STUDENT ORDER BY CLASS DESC,AGE DESC;41.SELECT A.TNAME,B.CNAME FROM TEACHER A JOIN COURSE B USING(TNO) WHERE A.TSEX=&#x27;男&#x27;;42.SELECT A.* FROM SCORE A WHERE DEGREE=(SELECT MAX(DEGREE) FROM SCORE B );43.SELECT SNAME FROM STUDENT A WHERE SSEX=(SELECT SSEX FROM STUDENT B WHERE B.SNAME=&#x27;李军&#x27;);44.SELECT SNAME FROM STUDENT A WHERE SSEX=(SELECT SSEX FROM STUDENT B WHERE B.SNAME=&#x27;李军&#x27; )AND CLASS=(SELECT CLASS FROM STUDENT C WHERE c.SNAME=&#x27;李军&#x27;);45.解法一：SELECT A.* FROM SCORE A JOIN (STUDENT B,COURSE C) USING(sno,CNO) WHERE B.SSEX=&#x27;男&#x27; AND C.CNAME=&#x27;计算机导论&#x27;;解法二：select * from score where sno in(select sno from student wheressex=&#x27;男&#x27;) and cno=(select cno from coursewhere cname=&#x27;计算机导论&#x27;);
参考答案二#1、查询Student表中的所有记录的Sname、Ssex和Class列。SELECT sname,ssex,class FROM student#2、查询教师所有的单位即不重复的Depart列。SELECT DISTINCT depart FROM teacher#3、查询Student表的所有记录。SELECT * FROM student#4、查询Score表中成绩在60到80之间的所有记录。SELECT * FROM score WHERE degree BETWEEN 60 AND 80#5、查询Score表中成绩为85，86或88的记录。SELECT * FROM score WHERE degree IN (85,86 ,88)#6、查询Student表中“95031”班或性别为“女”的同学记录。SELECT * FROM student WHERE ssex = &#x27;女&#x27; OR class = &#x27;95031&#x27;#7、以Class降序查询Student表的所有记录。SELECT * FROM student ORDER BY class DESC#8、以Cno升序、Degree降序查询Score表的所有记录。SELECT * FROM score ORDER BY cno,degree DESC#9、查询“95031”班的学生人数。SELECT COUNT(*) FROM student WHERE class = &#x27;95031&#x27;#10、查询Score表中的最高分的学生学号和课程号。SELECT sno,cno FROM score WHERE degree = (SELECT MAX(degree) FROM score)#11、查询‘3-105’号课程的平均分。SELECT AVG(degree) FROM score WHERE cno = &#x27;3-105&#x27;#12、查询Score表中至少有5名学生选修的并以3开头的课程的平均分数。SELECT AVG(degree) FROM score GROUP BY cno HAVING COUNT(sno) &gt;= 5AND cno LIKE &#x27;3%&#x27;#13、查询最低分大于70，最高分小于90的Sno列。SELECT sno FROM score GROUP BY snoHAVING MIN(degree) &gt; 70 AND MAX(degree) &lt; 90#14、查询所有学生的Sname、Cno和Degree列。SELECT sname,cno,degree FROM student,score WHERE student.SNO = score.SNO#15、查询所有学生的Sno、Cname和Degree列。SELECT sno,cname,degree FROM course, scoreWHERE course.cno = score.cno#16、查询所有学生的Sname、Cname和Degree列。SELECT sname, cname, degreeFROM score,course,studentWHERE student.SNO = score.SNOAND score.CNO = course.CNO#17、查询“95033”班所选课程的平均分。SELECT cno,AVG(degree) FROM score WHERE sno IN (SELECT sno FROM student WHERE class = &#x27;95033&#x27;)GROUP BY cnoSELECT AVG(degree) FROM scoreWHERE sno IN (SELECT sno FROM student WHERE class = &#x27;95033&#x27;)#18、假设使用如下命令建立了一个grade表：CREATE TABLE grade(low   INT,upp   INT,rank   CHAR(1));INSERT INTO grade VALUES(90,100,&#x27;A&#x27;);INSERT INTO grade VALUES(80,89,&#x27;B&#x27;);INSERT INTO grade VALUES(70,79,&#x27;C&#x27;);INSERT INTO grade VALUES(60,69,&#x27;D&#x27;);INSERT INTO grade VALUES(0,59,&#x27;E&#x27;);COMMIT;#现查询所有同学的Sno、Cno和rank列。SELECT o.sno,o.cno,g.rankFROM score o,grade gWHERE degree BETWEEN low AND upp#19、查询选修“3-105”课程的成绩高于“109”号同学成绩的所有同学的记录。SELECT * FROM scoreWHERE cno = &#x27;3-105&#x27;AND degree &gt; (SELECT degree FROM score WHERE sno =&#x27;109&#x27; AND cno = &#x27;3-105&#x27;)#20、查询score中选学一门以上课程的同学中分数为非最高分成绩的记录。SELECT * FROM score ,(SELECT cno ,MAX(degree) AS maxdFROM scoreGROUP BY cno) aWHERE sno IN (SELECT snoFROM score GROUP BY snoHAVING COUNT(*) &gt; 1) AND score.cno = a.cno AND score.degree != a.maxdSELECT * FROM score aWHERE sno IN (SELECT b.snoFROM score bGROUP BY b.snoHAVING COUNT(*) &gt; 1) AND a.degree !=(SELECT MAX(c.degree)FROM score cWHERE c.cno = a.cno)#21、查询成绩高于学号为“109”、课程号为“3-105”的成绩的所有记录。SELECT * FROM scoreWHERE degree &gt; (SELECT degreeFROM scoreWHERE sno = &#x27;109&#x27;AND cno = &quot;3-105&quot;)#22、查询和学号为108的同学同年出生的所有学生的Sno、Sname和Sbirthday列。SELECT a.sno ,a.sname,a.sbirthdayFROM student a,student bWHERE YEAR(a.sbirthday) = YEAR(b.sbirthday)AND b.sno = &#x27;108&#x27; AND a.sno != &#x27;108&#x27;SELECT sno ,sname,sbirthdayFROM studentWHERE YEAR(sbirthday) = (SELECT YEAR(sbirthday)FROM student WHERE sno = &#x27;108&#x27;)AND sno != &#x27;108&#x27;#23、查询“张旭“教师任课的学生成绩。SELECT sno,degreeFROM score,teacher,courseWHERE score.CNO = course.CNOAND teacher.tno = course.TNOAND tname = &#x27;张旭&#x27;#24、查询选修某课程的同学人数多于5人的教师姓名。SELECT DISTINCT teacher.TNAMEFROM course,teacher,scoreWHERE teacher.TNO = course.TNOAND course.cno = score.CNOAND course.cno IN(SELECT cno FROM scoreGROUP BY cnoHAVING COUNT(sno) &gt; 5)#25、查询95033班和95031班全体学生的记录。SELECT * FROM student WHERE class = &#x27;95033&#x27;OR class = &#x27;95031&#x27;ORDER BY class#26、查询存在有85分以上成绩的课程Cno.SELECT DISTINCT cnoFROM scoreWHERE degree &gt; 85#27、查询出“计算机系“教师所教课程的成绩表。SELECT tname,cname,degree,snoFROM score,course,teacherWHERE score.CNO = course.CNOAND teacher.TNO = course.TNOAND depart = &#x27;计算机系&#x27;#28、查询“计算机系”与“电子工程系“不同职称的教师的Tname和Prof。SELECT * FROM((SELECT tname AS ctname,prof AS cprofFROM teacherWHERE depart = &#x27;计算机系&#x27;) a,(SELECT tname AS etname,prof AS eprofFROM teacherWHERE depart = &#x27;电子工程系&#x27;) b)WHERE a.cprof != b.eprofSELECT tname,profFROM teacherWHERE depart IN (&#x27;计算机系&#x27;,&#x27;电子工程系&#x27;)GROUP BY profHAVING COUNT(*) &lt; 2#29、查询选修编号为“3-105“课程且成绩至少高于选修编号为“3-245”的同学的Cno、Sno和Degree,并按Degree从高到低次序排序。SELECT * FROM((SELECT *FROM scoreWHERE cno = &#x27;3-105&#x27;)  a,(SELECT *FROM scoreWHERE cno = &#x27;3-245&#x27;) b)WHERE a.sno = b.snoAND a.degree &gt; b.degreeORDER BY a.degree DESCSELECT Cno,Sno,Degree FROM score WHERE cno = &#x27;3-105&#x27;AND degree &gt; (SELECT MIN(degree) FROM scoreWHERE cno = &#x27;3-245&#x27;)ORDER BY degree DESC#30、查询选修编号为“3-105”且成绩高于选修编号为“3-245”课程的同学的Cno、Sno和Degree.SELECT Cno,Sno,Degree FROM score WHERE cno = &#x27;3-105&#x27;AND degree &gt; (SELECT MAX(degree) FROM scoreWHERE cno = &#x27;3-245&#x27;)#31、查询所有教师和同学的name、sex和birthday.SELECT tname,tsex,tbirthdayFROM teacherUNIONSELECT sname,ssex,sbirthdayFROM student#32、查询所有“女”教师和“女”同学的name、sex和birthday.SELECT sname,ssex,sbirthdayFROM studentWHERE ssex = &#x27;女&#x27;UNIONSELECT tname,tsex,tbirthdayFROM teacherWHERE tsex = &#x27;女&#x27;#33、查询成绩比该课程平均成绩低的同学的成绩表。SELECT * FROM score s1,(SELECT cno,AVG(degree) AS aFROM scoreGROUP BY cno) s2WHERE degree &lt; s2.a AND s1.cno = s2.cno#34、查询所有任课教师的Tname和Depart.SELECT DISTINCT tname,departFROM teacher,course,scoreWHERE teacher.TNO = course.TNOAND course.CNO = score.CNO#35  查询所有未讲课的教师的Tname和Depart. SELECT tname,departFROM teacherWHERE tno NOT IN (SELECT DISTINCT teacher.tnoFROM teacher,course,scoreWHERE teacher.TNO = course.TNOAND course.CNO = score.CNO)#36、查询至少有2名男生的班号。SELECT class FROM studentWHERE ssex = &#x27;男&#x27;GROUP BY classHAVING COUNT(*) &gt; 1#37、查询Student表中不姓“王”的同学记录。SELECT * FROM student WHERE sname NOT LIKE &#x27;王%&#x27;#38、查询Student表中每个学生的姓名和年龄。SELECT sname,2019 - YEAR(sbirthday)FROM student#39、查询Student表中最大和最小的Sbirthday日期值。SELECT MAX(sbirthday),MIN(sbirthday)FROM student#40、以班号和年龄从大到小的顺序查询Student表中的全部记录。SELECT * FROM studentORDER BY class DESC,SBIRTHDAY#41、查询“男”教师及其所上的课程。SELECT tname,cnameFROM teacher ,courseWHERE teacher.TNO = course.TNOAND tsex = &#x27;男&#x27;#42、查询最高分同学的Sno、Cno和Degree列。SELECT sno,cno,degreeFROM scoreWHERE degree = (SELECT MAX(degree) FROM score)#43、查询和“李军”同性别的所有同学的Sname.SELECT sname FROM student WHERE ssex = (SELECT ssex FROM studentWHERE sname=&#x27;李军&#x27;)AND sname != &#x27;李军&#x27;#44、查询和“李军”同性别并同班的同学Sname.SELECT sname FROM student WHERE ssex = (SELECT ssex FROM studentWHERE sname=&#x27;李军&#x27;)AND sname != &#x27;李军&#x27;AND class IN (SELECT class FROM studentWHERE sname = &#x27;李军&#x27;)#45、查询所有选修“计算机导论”课程的“男”同学的成绩表SELECT * FROM scoreWHERE sno IN (SELECT sno FROM studentWHERE ssex = &#x27;男&#x27;) AND cno = (SELECT cno FROM courseWHERE cname=&#x27;计算机导论&#x27;)

分享一个网页游戏，纯js实现青蛙跳

这是青蛙跳游戏。如果你是手机访问此页面，可以尝试横屏游戏玩法：左侧青蛙全部跳到右侧，右侧青蛙全部跳到左侧，闯关成功如果失败了，可以点击重置按钮


    function success(){
        var flag = true;
        for(var i = 1 ; i < 4 ; i++){
            if(document.getElementById(i).childNodes[0].getAttribute("value") == "left"){
                flag = false;
                break;
            }
        }
        if(document.getElementById("4").childNodes[0].getAttribute("value") != "null"){
            flag = false;	
        }   
        if(flag){
            alert("闯关成功");
        }
    }
    function jumpRight(div){
        var td = div.parentNode;
        if(td.id == "7"){
            return;
        }
        var nextTd = document.getElementById(td.id*1 + 1);
        if(nextTd.childNodes[0].getAttribute("value") == "null"){
            nextTd.appendChild(div);
            td.appendChild(nextTd.childNodes[0]);
            success();
            return;
        }
        if(td.id == "6"){
            return;
        }
        var next2Td = document.getElementById(td.id*1 + 2);
        if(next2Td.childNodes[0].getAttribute("value") == "null"){
            next2Td.appendChild(div);
            td.appendChild(next2Td.childNodes[0]);
            success();
            return;
        }
    }
    function jumpLeft(div){
        var td = div.parentNode;
        if(td.id == "1"){
            return;
        }
        var nextTd = document.getElementById(td.id*1 - 1);
        if(nextTd.childNodes[0].getAttribute("value") == "null"){
            nextTd.appendChild(div);
            td.appendChild(nextTd.childNodes[0]);
            success();
            return;
        }
        if(td.id == "2"){
            return;
        }
        var next2Td = document.getElementById(td.id*1 - 2);
        if(next2Td.childNodes[0].getAttribute("value") == "null"){
            next2Td.appendChild(div);
            td.appendChild(next2Td.childNodes[0]);
            success();
            return;
        }
    }
    function reset(){
        var tr=document.getElementById("tr");
        tr.innerHTML=''+
        ''+
        ''+
        ''+
        ''+
        ''+
        '';
    }

