下面是源代码，与上面的不太相同。源代码移动的是img标签，上面的用div标签代替，本主题中img标签有点击事件，游戏实现不了运用了三个图片，需要的话自行点击下载（图片另存为）left.jpgnull.jpgright.jpg
&lt;html&gt;	&lt;head&gt;		&lt;title&gt;青蛙跳&lt;/title&gt;		&lt;script type=&quot;text/javascript&quot;&gt; 			function success()&#123;				var flag = true;				for(var i = 1 ; i &lt; 4 ; i++)&#123;					if(document.getElementById(i).childNodes[0].name == &quot;left&quot;)&#123;						flag = false;						break;					&#125;				&#125;				if(document.getElementById(&quot;4&quot;).childNodes[0].name != &quot;null&quot;)&#123;					flag = false;					&#125;					if(flag)&#123;					alert(&quot;闯关成功&quot;);				&#125;			&#125;						function jumpRight(img)&#123;				var td = img.parentNode;				if(td.id == &quot;7&quot;)&#123;					return;				&#125;				var nextTd = document.getElementById(td.id*1 + 1);				if(nextTd.childNodes[0].name == &quot;null&quot;)&#123;					nextTd.appendChild(img);					td.appendChild(nextTd.childNodes[0]);					success();					return;				&#125;								if(td.id == &quot;6&quot;)&#123;					return;				&#125;				var next2Td = document.getElementById(td.id*1 + 2);				if(next2Td.childNodes[0].name == &quot;null&quot;)&#123;					next2Td.appendChild(img);					td.appendChild(next2Td.childNodes[0]);					success();					return;				&#125;						&#125;			function jumpLeft(img)&#123;				var td = img.parentNode;				if(td.id == &quot;1&quot;)&#123;					return;				&#125;				var nextTd = document.getElementById(td.id*1 - 1);				if(nextTd.childNodes[0].name == &quot;null&quot;)&#123;					nextTd.appendChild(img);					td.appendChild(nextTd.childNodes[0]);					success();					return;				&#125;				if(td.id == &quot;2&quot;)&#123;					return;				&#125;				var next2Td = document.getElementById(td.id*1 - 2);				if(next2Td.childNodes[0].name == &quot;null&quot;)&#123;					next2Td.appendChild(img);					td.appendChild(next2Td.childNodes[0]);					success();					return;				&#125;			&#125;		&lt;/script&gt;			&lt;/head&gt;	&lt;body&gt;		&lt;br/&gt;&lt;br/&gt;&lt;br/&gt;&lt;br/&gt;&lt;br/&gt;&lt;br/&gt;&lt;br/&gt;		&lt;table  cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; bordercolor=&quot;blue&quot;&gt;			&lt;tr id=&quot;tr&quot;&gt;				&lt;td id=&quot;1&quot; width=&quot;125&quot;&gt;&lt;img src=&quot;left.jpg&quot; onclick=&quot;jumpRight(this);&quot; name=&quot;left&quot;/&gt;&lt;/td&gt;				&lt;td id=&quot;2&quot; width=&quot;125&quot;&gt;&lt;img src=&quot;left.jpg&quot; onclick=&quot;jumpRight(this);&quot; name=&quot;left&quot;/&gt;&lt;/td&gt;				&lt;td id=&quot;3&quot; width=&quot;125&quot;&gt;&lt;img src=&quot;left.jpg&quot; onclick=&quot;jumpRight(this);&quot; name=&quot;left&quot;/&gt;&lt;/td&gt;				&lt;td id=&quot;4&quot; width=&quot;125&quot;&gt;&lt;img src=&quot;null.jpg&quot; name=&quot;null&quot;/&gt;&lt;/td&gt;				&lt;td id=&quot;5&quot; width=&quot;125&quot;&gt;&lt;img src=&quot;right.jpg&quot; onclick=&quot;jumpLeft(this);&quot; name=&quot;right&quot;/&gt;&lt;/td&gt;				&lt;td id=&quot;6&quot; width=&quot;125&quot;&gt;&lt;img src=&quot;right.jpg&quot; onclick=&quot;jumpLeft(this);&quot; name=&quot;right&quot;/&gt;&lt;/td&gt;				&lt;td id=&quot;7&quot; width=&quot;125&quot;&gt;&lt;img src=&quot;right.jpg&quot; onclick=&quot;jumpLeft(this);&quot; name=&quot;right&quot;/&gt;&lt;/td&gt;			&lt;/tr&gt;		&lt;/table&gt;	&lt;/body&gt;&lt;/html&gt;

这个主题我很喜欢，因为开发者不维护了，用着时间长了，发现了很多bug记得前段时间写了一个yilia主题常见问题及解决办法，内容有点长最近又发现了几个问题，这次再来写一个yilia主题常见问题及解决办法下
1.微信分享二维码失效微信分享二维码不显示，是百度生成二维码失效导致，换一个在线生成网址二维码的API接口即可 解决方法 定位文件themes\yilia\layout\_partial\post\share.ejs，修改微信分享img标签 将//pan.baidu.com/share/qrcode?url=改为//qr.liantu.com/api.php?text=即可（如果依然不显示，修改为http://qr.liantu.com/api.php?text=再试）
这里分享一个文章：在线生成网址二维码的API接口根据自己的需求更改在线生成网址二维码的API接口 2.浏览器控制台出现GET https://litten.me:9005/badj错误提示问题关于访问litten.me:9005的问题，这个主题的作者之前为了更好地完善这个主题，有时候会收集用户的客户端信息，详情请见https://github.com/litten/hexo-theme-yilia/issues/528，不过这个请求是异步的，不会影响博客加载速度，而且作者已经不维护了，所以关不关都行。如果不想被统计（或不想让控制台报错），看解决办法 解决办法 定位文件themes\yilia\source\main.0cf68a.js 在文件中查找//litten.me:9005/badjs/ 将这段代码所在的函数删除
我删除的内容（就是将192:到193之间的内容全部删除） 192: function(e, t, n) &#123; &quot;use strict&quot;; function o(e) &#123; var t = new RegExp(&quot;(^|&amp;)&quot; + e + &quot;=([^&amp;]*)(&amp;|$)&quot;,&quot;i&quot;) , n = window.location.search.substr(1).match(t); return null != n ? unescape(n[2]) : null &#125; var r = n(388); if (n(197), window.BJ_REPORT) &#123; BJ_REPORT.init(&#123; id: 1 &#125;), BJ_REPORT.init(&#123; id: 1, uin: window.location.origin, combo: 0, delay: 1e3, url: &quot;//litten.me:9005/badjs/&quot;, ignore: [/Script error/i], random: 1, repeat: 5e5, onReport: function(e, t) &#123;&#125;, ext: &#123;&#125; &#125;); var i = window.location.host , a = top === window , u = !(/localhost/i.test(i) || /127.0.0.1/i.test(i) || /0.0.0.0/i.test(i)); a &amp;&amp; u &amp;&amp; BJ_REPORT.report(&quot;yilia-&quot; + window.location.host); var l = o(&quot;f&quot;) , c = &quot;yilia-from&quot;; l ? (a &amp;&amp; BJ_REPORT.report(&quot;from-&quot; + l), r.set(c, l)) : document.referrer.indexOf(window.location.host) &gt;= 0 ? (l = r.get(c), l &amp;&amp; a &amp;&amp; BJ_REPORT.report(&quot;from-&quot; + l)) : r.remove(c) &#125; e.exports = &#123; init: function() &#123;&#125; &#125; &#125;,
删除函数的调用 依然是这个文件搜索192，会看到n(386),n(192);，将n(192);删除，n(386),改为n(386);
到此，问题解决 3.yilia主题移动端目录问题如果目录文字过长，你会发现如下问题目录左侧溢出，如果想解决，参看以下解决办法 解决办法 修改移动端css 定位文件themes\yilia\source\main.0cf68a.css，查找@media screen and (max-width: 800px)，在下面添加以下内容
.toc-container.tooltip-left .tooltip-east .tooltip-content .toc-article&#123; max-height: 350px; font-size: smaller&#125;.toc-container.tooltip-left .tooltip-east .tooltip-content .toc-article .toc &#123; width: 250px&#125;.toc-container.tooltip-left .tooltip-east .tooltip-content .toc-article li &#123; white-space: normal&#125;
第一个样式是修改目录高度以及文字大小 第二个样式是修改目录宽度 第三个样式修改目录文字是否换行（pc端页面，标题文字设置的不换行，所以出现了目录左侧溢出）
修改完效果如下： 4.yilia主题控制台两个警告提示不匹配的结束标记。通过控制台，可以发现问题提示在p标签 &lt;p q-show=&quot;jsonFail&quot; style=&quot;padding: 20px; font-size: 12px;&quot;&gt; 缺失模块。&lt;br/&gt;1、请确保node版本大于6.2&lt;br/&gt;2、在博客根目录（注意不是yilia根目录）执行以下命令：&lt;br/&gt; npm i hexo-generator-json-content --save&lt;br/&gt;&lt;br/&gt; 3、在根目录_config.yml里添加配置：&lt;pre style=&quot;font-size: 12px;&quot; q-show=&quot;jsonFail&quot;&gt; jsonContent: meta: false pages: false posts: title: true date: true path: true text: false raw: false content: false slug: false updated: false comments: false link: false permalink: false excerpt: false categories: false tags: true&lt;/pre&gt; &lt;/p&gt; 解决办法p标签不能嵌套pre标签（通过控制台查看元素可以发现p标签和pre标签是并列出现的，浏览器将外层的p标签变成了两个p标签，与pre标签并列），将&lt;/p&gt;移至pre标签之前，取消嵌套 注释结尾的字符不符合要求。应为 “--&gt;” 字符。我发现问题出现在预加载注释上&lt;!-- element will get class pswp__preloader--active when preloader is running --&gt;--符号出现了问题 解决办法这个就是一个简单的注释，在部分浏览器会出现提示，将--符号误以为注释结尾，本身没有问题如果想改的话，将--改为——，控制台提示消失 5.移动端归档页面（非主页）内容过短导致样式问题归档页面，随笔页面，这些页面差不多，如果最后一页内容过短，点击所有文章，背景色和背景层的高度出现问题先来看看问题的图片
最后一页内容过少，导致点击所有文章按钮，所有文章和背景层的背景色没有将页面充满，使页面的下半部分出现了白色透明背景 解决办法这个问题只出现在移动端页面，我的方法是通过js解决
找到控制移动端动画的js代码 在js代码中添加判断，网页可见区域高度是否小于屏幕分辨率的高度 如果小于，对id&#x3D;”container”的div标签添加height属性 height的值为屏幕分辨率的高度，使所有文章和背景层的背景色将页面充满
具体实现方法 1.在主题中查找document.querySelector(&quot;#container&quot;).addEventListener(&quot;scroll&quot;，这段代码是在一个叫function s()的函数我对js代码进行了解压缩，看得直接明了些 2.function s()是移动端页面才执行的函数，通过下面的判断可以看出（因为问题只出现在移动端，所以只在控制移动端js的代码中添加） 3.在function s()函数中添加判断(在document.querySelector(&quot;#container&quot;).addEventListener(&quot;scroll&quot;之前添加即可)
function s() &#123; //开始添加 //添加比较body总高度与浏览器页面可用高度 if (document.body.clientHeight &lt; window.innerHeight) &#123; var n = document.querySelector(&quot;#container&quot;); var height = window.innerHeight; n.setAttribute(&quot;style&quot;, &quot;height:&quot; + height + &quot;px&quot;) &#125; //结束 document.querySelector(&quot;#container&quot;).addEventListener(&quot;scroll&quot;, function(t) &#123; a() &#125;), 这里解释一下为什么判断网页可见区域高度是否小于屏幕分辨率的高度如果不添加这个判断，会对所有的页面都添加这个height属性，移动端css中 #container, body, html &#123; height: auto; overflow-x: hidden; overflow-y: auto;&#125; height:auto便失去了意义附上几个获取高度的属性
网页可见区域高：document.body.clientHeight（body总高度）网页可见区域高：document.body.offsetHeight（body总高度）网页正文全文高：document.body.scrollHeight（body总高度）浏览器页面可用高度：document.documentElement.clientHeight&#x2F;window.innerHeight屏幕分辨率的高：window.screen.height（屏幕分辨率高度）屏幕可用工作区高：window.screen.availHeight&#x2F;screen.availHeight（屏幕分辨率高度）
alert(&quot;body总高度：&quot;+document.body.clientHeight)//body总高度alert(&quot;body总高度：&quot;+document.body.offsetHeight)//body总高度alert(&quot;body总高度：&quot;+document.body.scrollHeight)//body总高度alert(&quot;浏览器页面可用高度：&quot;+document.documentElement.clientHeight)//浏览器页面可用高度alert(&quot;浏览器页面可用高度：&quot;+window.innerHeight)//浏览器页面可用高度alert(&quot;屏幕分辨率的高：&quot;+window.screen.height)//屏幕分辨率高度alert(&quot;屏幕分辨率的高：&quot;+window.screen.availHeight)//屏幕分辨率高度alert(&quot;屏幕分辨率的高：&quot;+screen.availHeight)//屏幕分辨率高度 这里用的是document.body.clientHeight和window.innerHeight 6.手机端主页分页过多，点击某一页，出现下一页标签换行页数过多，点击中间的一页可能会出现下一页标签换行一半，即 下一页在上一行， »在下一行换行的问题解决不了，分页过多，一行显示不下，自然会把多余的内容挤到下一行来，即使你把上下页标签的margin属性设为0，可能暂时没有问题，但是随着文章越来越多，迟早会被挤下来 这里解决一下a标签：下一页 » 换行一半问题既然a标签换行不可避免，但是换行一半是可以避免的将上下页a标签转为行内块当a标签的大小不足以使它在一行显示，a标签内容会全部换行，而不会出现换行一半的现象即在css中对#page-nav .extend添加display:inline-block; /* 添加上下页标签转为行内块 */#page-nav .extend &#123; display:inline-block; color:#4d4d4d; margin:0 27px; opacity:1&#125; 7.手机端开启目录，页面出现了滚动条yilia主题，移动端适配有很多问题，之前的页面滚动动画、返回顶部按钮和目录，开发者应该是没有对移动端进行适配测试（可能是先在pc上实现，再往移动端适配）开发者已经不维护这个主题，本人在移动端启用发现了很多问题移动端文章开启目录，点击所有文章按钮，页面右侧会出现滚动条，关闭所有文章后，页面弹动效果中也会出现滚动条 解决办法 在themes\yilia\source\main.0cf68a.css中查找.mid-col.show，添加overflow: hidden
/* 添加overflow: hidden */.mid-col.show &#123; background: none; opacity: .9; overflow: hidden&#125;
在移动端css下，即@media screen and (max-width: 800px)下，隐藏#container标签滚动条
/* 隐藏滚动条 */#container::-webkit-scrollbar &#123; width: 0&#125; 问题解决 8.代码块行号显示错乱这个问题是white-space: pre-wrap;自动换行造成的 解决办法在themes\yilia\source\main.0cf68a.css中查找white-space: pre-wrap;，将其删除 /* 删除white-space: pre-wrap; */pre &#123; overflow: auto; white-space: pre; word-wrap: break-word&#125; 使用不自动换行的white-space:pre;样式，代码块溢出部分会自动在底部出现滚动条，行号错乱问题就没有了。如果代码下面的滚动条看不见，在css中添加 /* figure滚动条优化 */.article-entry figure::-webkit-scrollbar-thumb,.article-entry figure::-webkit-scrollbar-thumb:hover&#123; background-color: #bbbbbb;&#125; 修改滚动条颜色（滚动条默认颜色与代码块背景色冲突） 9.文章内的超链接超出页面问题当页面进行缩放时，这个区域可能会超出页面。 解决办法css中对a标签添加word-wrap: break-word属性指定如果足够长得话，应该换行： /* 添加word-wrap: break-word */a &#123; background: transparent; text-decoration: none; color: #08c; word-wrap: break-word&#125;

编译器快捷键ctrl+s保存 ctrl+c复制 ctrl+v粘贴 ctrl+z上一步 ctrl+y下一步&lt;!DOCTYPE HTML&gt;文档的声明，浏览器按W3C标准解析网页&lt;html&gt; &lt;/html&gt;跟标签 &lt;meta charset=&quot;utf-8&quot;&gt;指定文件标准编码的种类gb2312&#x2F;gbk&#x2F;ANSIC 国标 uft-8 国际通用标准

&lt;title&gt;&lt;/title&gt;&lt;body&gt;&lt;/body&gt;
html4.01 html5正式版1.h标签 h1~h6默认加粗，h1只能用一次，权重最高2.p标签 用于显示文章的段落3.div标签 用于模式布局，使用频率最高单标签 img用于显示图片&lt;img src=&quot;图片路径&quot; alt=&quot;替换文本&quot; width=&quot;宽度&quot; height=&quot;高度&quot;&gt;注：图片名称最好不要出现中文css样式表：又名层叠样式，通过css来修饰标签样式
&lt;style&gt;    h3&#123;        color: red;    &#125;&lt;/style&gt;
内部css样式表color:颜色 font-size:表示文字大小，单位px：像素单位font-weight:文字是否加粗  blod 加粗 normal 正常(多适用于h标签)font-family:”微软雅黑” 文字宋体，还可用于”宋体”text-align:表示文字的对齐方式 left 左对齐（默认） center 居中 right 右对齐width:容器的宽度（适用于div标签） 单位px或百分比margin:0 auto div标签居中 容器水平方向居中text-indent:表示首行文字的缩进 单位 em：表示一个字符的大小例：text-indent:2emline-height:行高（可理解为行间距） 特点：文本会在行高中自动垂直居中 单位：pxletter-spacing:字符之间距离 pxfont-style:文本的标识 italic 倾斜 narmal 正常显示（默认）text-decoration:文本的修饰 none 表示去掉所有的修饰符如：下划线 underline 加下划线 主要适用于 a标签a标签（超链接）&lt;a href=&quot;页面地址&quot; title=&quot;提示文字&quot; target=&quot;打开方式&quot;&gt;中间内容&lt;/a&gt; target:_blank 在新页面打开，默认原页面跳转伪类选择器
a:hover&#123;&#125;
注：文本路径要用相对路径代码注释：选中相应的代码，ctrl+/，即可注释css:/*被注释的css*/html:&lt;!--被注释的html代码--&gt;class选择器
&lt;style&gt;    .aaa&#123;    &#125;&lt;/style&gt;&lt;div class=&quot;aaa&quot;&gt;
注：”aaa”可换特点：根据元素的class属性来查找元素 好处：可以区分相同元素的不同样式列表结构ul&gt;li 双标签 无序列表ol&gt;li 双标签 有序列表dl&gt;dd&#x2F;dt 双标签 定义列表&#x2F;描述列表列表结构 css样式list-style:列表风格 none 去掉小黑点（去掉li标签的默认修饰符）选择器结构写法：选择器1 选择器2 选择器3 {…} 空格表示“的”的意思防止各模式样式冲突 通常以模块的根节点作为结构选择器的第一级选择器 通常都是class选择器
&lt;style&gt;    .aaa&#123;    &#125;    #.list&#123;    &#125;&lt;/style&gt;&lt;div class=&quot;aaa&quot;&gt;&lt;/div&gt;&lt;div id=&quot;list&quot;&gt;&lt;/div&gt;
#是id选择器选择器优先级行间样式 权重：1000&gt;id选择器 权重：100&gt;class选择器 权重：10&gt;标签选择器 权重：1&gt;通配符选择器不要写行间样式，不要用id选择器(推荐)

边框样式（div标签）border: 5px soild red 粗细 样式 颜色soild实线 dashed虚线 dotted点划线border可以分开指定 border-();()可以是top 即border-top；上边框  left左边框  right右边框  bottom下边框背景 backgroundbackground-color:背景颜色 background-image:背景图片 url(图片路径)background-repeat:背景图平铺（重复） no-repeat repeat-x repeat-ybackground-position:背景位置 x轴方向 y轴方向（1）英文： center left right bottom top（2）数字： x y &#x3D;&gt;起始点 0 0（3）数字+中文（4）一个值时，第二个默认是center简写：background: red url() 0px center no-repeat盒子margin外边距 px1个值 4个方向  2个值 上下 左右  3个值 上 左右下  4个值 顺时针方向 上右下左可以分开写margin-();内边距 padding px同外边距

块元素：独占一行的元素div、h、p、ul、li、ol、dl、ddp标签不能嵌套任何标签，其余可以嵌套行内元素：不会独占一行 a span标签可嵌套任何标签img：行内块元素 本质上是行内元素 但支持宽和高样式元素之间转换display:inline 转行内 block 转块元素 inline-block 转行内块

浮动float: left(right);左（右）浮动  解决块元素在一行显示停止条件：（1）父元素的边缘（2）其他的浮动元素浮动过程中，宽度不够会挤下来清除浮动
&lt;div class=&quot;clear&quot;&gt;&lt;/div&gt;.class&#123;    clear: both;&#125;
清除浮动带来的影响，就像一个挡板一样
.clearfix:after&#123;    display: block;    content: &#x27; &#x27;;    clear: both;&#125;
